import { collection, onSnapshot, addDoc, doc, updateDoc, setDoc, query, orderBy, deleteDoc } from "firebase/firestore";

const App: React.FC = () => {
  // --- STATE ---

  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('serviplus_current_user');
