  const [commissionRate, setCommissionRate] = useState<number>(COMMISSION_RATE);

  // Error Handling State
  const [isOfflineMode, setIsOfflineMode] = useState(false);
  const [connectionError, setConnectionError] = useState('');
  const [showOfflineBanner, setShowOfflineBanner] = useState(true);

  // --- FIREBASE LISTENERS ---

  // Sync Users
  useEffect(() => {
    let unsubscribe = () => {};
    try {
        unsubscribe = onSnapshot(collection(db, "users"), (snapshot) => {
        const loadedUsers = snapshot.docs.map(doc => ({ ...doc.data(), id: doc.id } as User));
        setIsOfflineMode(false);
        setConnectionError('');

        if (loadedUsers.length === 0) {
            setUsers(MOCK_USERS);
        } else {
            setUsers(loadedUsers);
        }
        }, (error) => {
            console.warn("Firestore Users Sync Warning (Switching to Demo Mode):", error.code);
            setIsOfflineMode(true);
            setConnectionError("Mode Démonstration (Base de données non connectée)");
            setUsers(prev => prev.length > 0 ? prev : MOCK_USERS);
        });
    } catch (err) {
        console.warn("Firestore init failed:", err);
        setIsOfflineMode(true);
        setConnectionError("Mode Démonstration (Offline)");
        setUsers(MOCK_USERS);
    }
    return () => unsubscribe();
  }, []);

  // Sync Missions
  useEffect(() => {
    let unsubscribe = () => {};
    try {
        const q = query(collection(db, "missions"), orderBy("createdAt", "desc"));
        unsubscribe = onSnapshot(q, (snapshot) => {
        const loadedMissions = snapshot.docs.map(doc => ({ ...doc.data(), id: doc.id } as Mission));
        setMissions(loadedMissions);
        }, (error) => {
            // Silent fail for missions, fallback handled by offline mode logic
            setMissions(prev => prev.length > 0 ? prev : MOCK_MISSIONS);
        });
    } catch (err) {
        setMissions(MOCK_MISSIONS);
    }
    return () => unsubscribe();
  }, []);

  // Sync Settings
  useEffect(() => {
