Déplacement de la modale de paiement : Elle ne s'affiche plus à la création, mais lors de la validation finale de la mission pour libérer les fonds au prestataire.

<content><![CDATA[
import React, { useState } from 'react';
import { User, ServiceCategory, Mission, MissionStatus, UserRole } from '../types';
import { SERVICE_ICONS, LAUNDRY_MIN_QTY, LAUNDRY_MIN_PRICE, LAUNDRY_EXTRA_PRICE } from '../constants';
import { Plus, MapPin, Calendar, Clock, Calculator, Sparkles, Loader2, AlertCircle, Star, CheckCircle, AlertTriangle, Shirt, Navigation, User as UserIcon, Save, Camera, Lock, Phone, Home, Smartphone, Copy, ArrowRight, Wallet } from 'lucide-react';
import { estimateMissionDetails } from '../services/geminiService';

interface ClientDashboardProps {
  currentUser: User;
  missions: Mission[];
  baseRates: Record<ServiceCategory, number>;
  commissionRate: number;
  onAddMission: (mission: Mission) => void;
  onValidateMission: (missionId: string) => void;
  onDisputeMission: (missionId: string, reason: string) => void;
  onRateMission: (missionId: string, rating: number, comment: string) => void;
  onUpdateUser: (data: Partial<User>) => void;
}

// Payment Providers Configuration
const PAYMENT_METHODS = [
  { id: 'wave', name: 'Wave', number: '0749793516', color: 'bg-blue-500 text-white', logo: '🌊' },
  { id: 'om', name: 'Orange Money', number: '0749793516', color: 'bg-orange-500 text-white', logo: '🟠' },
  { id: 'mtn', name: 'MTN MoMo', number: '0554199359', color: 'bg-yellow-400 text-yellow-900', logo: '🟡' },
  { id: 'moov', name: 'Moov Money', number: '0171030334', color: 'bg-green-600 text-white', logo: '🔵' }
];

const ClientDashboard: React.FC<ClientDashboardProps> = ({ 
  currentUser, 
  missions, 
  baseRates,
  commissionRate,
  onAddMission,
  onValidateMission,
  onDisputeMission,
  onRateMission,
  onUpdateUser
}) => {
  const [activeTab, setActiveTab] = useState<'HOME' | 'PROFILE'>('HOME');

  // --- MISSION CREATION STATE ---
  const [isCreating, setIsCreating] = useState(false);
  const [loadingAi, setLoadingAi] = useState(false);

  const [category, setCategory] = useState<ServiceCategory>(ServiceCategory.CLEANING);
  const [description, setDescription] = useState('');
  const [location, setLocation] = useState(currentUser.address || '');
  const [date, setDate] = useState('');
  const [clothesCount, setClothesCount] = useState<number>(LAUNDRY_MIN_QTY); // Default minimum
  const [startTime, setStartTime] = useState('09:00');
  const [endTime, setEndTime] = useState('11:00');

  // --- PAYMENT STATE ---
  const [showPaymentModal, setShowPaymentModal] = useState(false);
  const [selectedPaymentMethod, setSelectedPaymentMethod] = useState<typeof PAYMENT_METHODS[0] | null>(null);
  // We now use missionToPay for existing missions at the end of the flow
  const [missionToPay, setMissionToPay] = useState<Mission | null>(null);

  // --- PROFILE EDIT STATE ---
  const [profileForm, setProfileForm] = useState({
    name: currentUser.name,
    phone: currentUser.phone,
    address: currentUser.address || '',
    password: currentUser.password || ''
  });
  const [newAvatar, setNewAvatar] = useState<string | null>(null);

  // --- MODAL STATES ---
  const [selectedMissionId, setSelectedMissionId] = useState<string | null>(null);
  const [modalType, setModalType] = useState<'DISPUTE' | 'RATING' | null>(null);
  const [inputText, setInputText] = useState('');
  const [ratingValue, setRatingValue] = useState(5);

  const myMissions = missions.filter(m => m.clientId === currentUser.id);

  // --- HELPERS ---

  const getDuration = (): number => {
    if (!startTime || !endTime) return 0;
    const [startH, startM] = startTime.split(':').map(Number);
    const [endH, endM] = endTime.split(':').map(Number);
    const startMinutes = startH * 60 + startM;
    const endMinutes = endH * 60 + endM;
    const diffMinutes = endMinutes - startMinutes;
    return diffMinutes > 0 ? diffMinutes / 60 : 0;
  };

  const duration = getDuration();

  const handleAiEstimate = async () => {
    if (!description) return;
    setLoadingAi(true);
    const result = await estimateMissionDetails(description, category);
    if (result) {
      const estimatedHours = result.estimatedDuration;
      const [startH, startM] = startTime.split(':').map(Number);
      const totalStartMinutes = startH * 60 + startM;
      const totalEndMinutes = totalStartMinutes + (estimatedHours * 60);
      const endH = Math.floor(totalEndMinutes / 60) % 24;
      const endM = Math.floor(totalEndMinutes % 60);
      const formattedEnd = `${String(endH).padStart(2, '0')}:${String(endM).padStart(2, '0')}`;
      setEndTime(formattedEnd);
      setDescription(result.descriptionImprovement);
    }
    setLoadingAi(false);
  };

  const calculatePrice = () => {
    if (category === ServiceCategory.LAUNDRY) {
        if (clothesCount <= LAUNDRY_MIN_QTY) {
            return LAUNDRY_MIN_PRICE;
        }
        const extraItems = clothesCount - LAUNDRY_MIN_QTY;
        return LAUNDRY_MIN_PRICE + (extraItems * LAUNDRY_EXTRA_PRICE);
    }
    const rate = baseRates[category];
    return Math.round(rate * duration);
  };

  const handleCreateMission = (e: React.FormEvent) => {
    e.preventDefault();
    if (duration <= 0) return;

    const totalPrice = calculatePrice();
    const commission = totalPrice * commissionRate;

    let missionTitle = `${category} - ${location}`;
    if (category === ServiceCategory.LAUNDRY) {
        missionTitle = `${category} (${clothesCount} vêtements) - ${location}`;
    }

    const newMission: Mission = {
      id: `m${Date.now()}`,
      title: missionTitle,
      clientId: currentUser.id,
      clientName: currentUser.name,
      category,
      description,
      location,
      date: `${date}T${startTime}`,
      endTime: `${date}T${endTime}`,
      durationHours: duration,
      quantity: category === ServiceCategory.LAUNDRY ? clothesCount : undefined,
      totalPrice,
      commission,
      providerAmount: totalPrice - commission,
      status: MissionStatus.PENDING,
      createdAt: new Date().toISOString()
    };

    // Directly add mission without payment
    onAddMission(newMission);
    setIsCreating(false);
    resetForm();
  };

  const handleOpenPayment = (mission: Mission) => {
      setMissionToPay(mission);
      setSelectedPaymentMethod(null);
      setShowPaymentModal(true);
  };

  const handleConfirmPayment = () => {
      if (missionToPay) {
          onValidateMission(missionToPay.id);
          setShowPaymentModal(false);
          setMissionToPay(null);
      }
  };

  const handleProfileSubmit = (e: React.FormEvent) => {
      e.preventDefault();
      onUpdateUser({
          name: profileForm.name,
          phone: profileForm.phone,
          address: profileForm.address,
          password: profileForm.password,
          avatarUrl: newAvatar || currentUser.avatarUrl
      });
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          const reader = new FileReader();
          reader.onloadend = () => {
              setNewAvatar(reader.result as string);
          };
          reader.readAsDataURL(file);
      }
  };

  const resetForm = () => {
    setDescription('');
    setDate('');
    setStartTime('09:00');
    setEndTime('11:00');
    setClothesCount(LAUNDRY_MIN_QTY);
  };

  const handleLocateMe = () => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition((position) => {
        setLocation(`${position.coords.latitude}, ${position.coords.longitude}`);
      }, (error) => {
        console.error("Geolocation error:", error);
        alert("Impossible de récupérer votre position. Veuillez l'entrer manuellement.");
      });
    }
  };

  // Modal Handlers
  const openDispute = (id: string) => {
    setSelectedMissionId(id);
    setModalType('DISPUTE');
    setInputText('');
  };

  const openRating = (id: string) => {
    setSelectedMissionId(id);
    setModalType('RATING');
    setInputText('');
    setRatingValue(5);
  };

  const submitModal = () => {
    if (!selectedMissionId) return;
    if (modalType === 'DISPUTE') {
      onDisputeMission(selectedMissionId, inputText);
    } else if (modalType === 'RATING') {
      onRateMission(selectedMissionId, ratingValue, inputText);
    }
    setModalType(null);
    setSelectedMissionId(null);
  };

  // --- RENDER FUNCTIONS ---

  const renderPaymentModal = () => {
      if (!showPaymentModal || !missionToPay) return null;

      return (
          <div className="fixed inset-0 bg-black bg-opacity-60 flex items-center justify-center z-50 p-4 backdrop-blur-sm animate-fade-in">
              <div className="bg-white rounded-2xl w-full max-w-md overflow-hidden shadow-2xl">
                  <div className="bg-green-600 p-6 text-white text-center">
                      <h3 className="text-xl font-bold mb-1">Paiement Final</h3>
                      <p className="text-green-100 text-sm">Réglez la prestation pour clôturer la mission</p>
                  </div>

                  <div className="p-6">
                      <div className="text-center mb-6">
                          <span className="text-gray-500 text-sm uppercase tracking-wide">Montant à régler</span>
                          <div className="text-4xl font-extrabold text-green-700 mt-1">
                              {missionToPay.totalPrice.toLocaleString()} <span className="text-xl text-gray-500">FCFA</span>
                          </div>
                          <p className="text-xs text-gray-400 mt-1">Ce montant sera reversé au prestataire</p>
                      </div>

                      {!selectedPaymentMethod ? (
                          <div className="space-y-3">
                              <p className="text-sm font-bold text-gray-700 mb-2">Choisissez votre moyen de paiement :</p>
                              {PAYMENT_METHODS.map(method => (
                                  <button
                                      key={method.id}
                                      onClick={() => setSelectedPaymentMethod(method)}
                                      className={`w-full flex items-center justify-between p-4 rounded-xl border border-gray-200 hover:border-green-300 hover:shadow-md transition-all group`}
                                  >
                                      <div className="flex items-center">
                                          <span className="text-2xl mr-3">{method.logo}</span>
                                          <span className="font-bold text-gray-800 group-hover:text-green-700">{method.name}</span>
                                      </div>
                                      <ArrowRight size={18} className="text-gray-300 group-hover:text-green-500"/>
                                  </button>
                              ))}
                          </div>
                      ) : (
                          <div className="animate-fade-in">
                              <button 
                                onClick={() => setSelectedPaymentMethod(null)}
                                className="text-sm text-gray-500 hover:text-green-600 mb-4 flex items-center"
                              >
                                  <ArrowRight size={14} className="rotate-180 mr-1"/> Changer de méthode
                              </button>

                              <div className={`p-5 rounded-xl ${selectedPaymentMethod.color} mb-6 shadow-lg`}>
                                  <div className="flex justify-between items-center mb-4">
                                      <span className="font-bold text-lg">{selectedPaymentMethod.name}</span>
                                      <span className="text-2xl">{selectedPaymentMethod.logo}</span>
                                  </div>
                                  <p className="text-sm opacity-90 mb-1">Envoyez le montant au numéro :</p>
                                  <div className="flex items-center justify-between bg-white/20 p-3 rounded-lg backdrop-blur-sm">
                                      <span className="font-mono text-2xl font-bold tracking-wider">{selectedPaymentMethod.number}</span>
                                      <button 
                                        onClick={() => {navigator.clipboard.writeText(selectedPaymentMethod.number); alert("Numéro copié !")}}
                                        className="p-2 hover:bg-white/20 rounded-full transition-colors"
                                      >
                                          <Copy size={18} />
                                      </button>
                                  </div>
                              </div>

                              <div className="bg-gray-50 p-4 rounded-xl border border-gray-200 mb-6">
                                  <p className="text-xs text-gray-500 text-center">
                                      En cliquant sur "Confirmer le paiement", la mission sera marquée comme terminée et le prestataire sera notifié.
                                  </p>
                              </div>

                              <button
                                  onClick={handleConfirmPayment}
                                  className="w-full py-4 bg-green-600 hover:bg-green-700 text-white rounded-xl font-bold shadow-lg shadow-green-200 transition-all flex justify-center items-center"
                              >
                                  <CheckCircle size={20} className="mr-2" />
                                  Confirmer le paiement
                              </button>
                          </div>
                      )}
                  </div>

                  {!selectedPaymentMethod && (
                      <div className="bg-gray-50 p-4 border-t border-gray-100 flex justify-center">
                          <button 
                              onClick={() => setShowPaymentModal(false)}
                              className="text-gray-500 font-medium hover:text-red-500 transition-colors"
                          >
                              Annuler
                          </button>
                      </div>
                  )}
              </div>
          </div>
      );
  };

  const renderModal = () => {
    if (!modalType) return null;
    const isDispute = modalType === 'DISPUTE';

    return (
      <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
        <div className="bg-white rounded-2xl p-6 w-full max-w-md animate-fade-in">
          <h3 className={`text-xl font-bold mb-4 ${isDispute ? 'text-red-600' : 'text-blue-600'}`}>
            {isDispute ? 'Signaler un litige' : 'Noter le prestataire'}
          </h3>

          {!isDispute && (
            <div className="flex justify-center space-x-2 mb-4">
              {[1, 2, 3, 4, 5].map((star) => (
                <button
                  key={star}
                  onClick={() => setRatingValue(star)}
                  className={`transition-transform hover:scale-110 ${star <= ratingValue ? 'text-yellow-400' : 'text-gray-300'}`}
                >
                  <Star size={32} fill="currentColor" />
                </button>
              ))}
            </div>
          )}

          <textarea
            value={inputText}
            onChange={(e) => setInputText(e.target.value)}
            className="w-full border border-gray-300 rounded-lg p-3 mb-4 focus:ring-2 focus:ring-blue-500"
            rows={4}
            placeholder={isDispute ? "Décrivez le problème rencontré..." : "Votre avis sur la prestation..."}
          />

          <div className="flex space-x-3">
            <button 
              onClick={() => setModalType(null)}
              className="flex-1 py-2 text-gray-600 hover:bg-gray-100 rounded-lg"
            >
              Annuler
            </button>
            <button 
              onClick={submitModal}
              disabled={!inputText}
              className={`flex-1 py-2 text-white rounded-lg font-bold ${
                isDispute ? 'bg-red-600 hover:bg-red-700' : 'bg-blue-600 hover:bg-blue-700'
              }`}
            >
              Envoyer
            </button>
          </div>
        </div>
      </div>
    );
  };

  const renderCreateMission = () => {
     const price = calculatePrice();
    return (
      <div className="bg-white rounded-2xl shadow-xl p-6 max-w-2xl mx-auto animate-fade-in">
        <h2 className="text-2xl font-bold text-blue-900 mb-6">Publier une nouvelle mission</h2>
        <form onSubmit={handleCreateMission} className="space-y-6">
          {/* Service Selection */}
          <div className="grid grid-cols-3 gap-3">
            {Object.values(ServiceCategory).map((cat) => {
              const Icon = SERVICE_ICONS[cat];
              return (
                <button
                  key={cat}
                  type="button"
                  onClick={() => setCategory(cat)}
                  className={`flex flex-col items-center justify-center p-4 rounded-xl border transition-all ${
                    category === cat 
                      ? 'border-blue-500 bg-blue-50 text-blue-600 ring-2 ring-blue-200' 
                      : 'border-gray-200 hover:bg-gray-50 text-gray-600'
                  }`}
                >
                  <Icon size={24} className="mb-2" />
                  <span className="text-xs font-medium text-center">{cat}</span>
                </button>
              );
            })}
          </div>

          {/* Special Laundry Input */}
          {category === ServiceCategory.LAUNDRY && (
             <div className="bg-blue-50 p-4 rounded-xl border border-blue-100">
                <label className="block text-sm font-bold text-blue-900 mb-2 flex items-center">
                    <Shirt size={18} className="mr-2" />
                    Nombre de vêtements à laver
                </label>
                <div className="space-y-2">
                    <input
                        type="number"
                        min={LAUNDRY_MIN_QTY}
                        value={clothesCount}
                        onChange={(e) => setClothesCount(parseInt(e.target.value) || LAUNDRY_MIN_QTY)}
                        className="w-full p-3 border border-blue-300 rounded-lg focus:ring-2 focus:ring-blue-500 text-lg font-bold text-center"
                    />
                    <p className="text-xs text-blue-600 text-center">
                        Minimum {LAUNDRY_MIN_QTY} vêtements ({LAUNDRY_MIN_PRICE} FCFA) <br/>
                        + {LAUNDRY_EXTRA_PRICE} FCFA par vêtement supplémentaire.
                    </p>
                </div>
             </div>
          )}

          {/* Description with AI */}
          <div className="space-y-2">
            <label className="block text-sm font-medium text-gray-700">Description du besoin</label>
            <textarea
              required
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              rows={3}
              placeholder="Ex: J'ai besoin d'un nettoyage complet..."
            />
            {category !== ServiceCategory.LAUNDRY && (
                <button
                type="button"
                onClick={handleAiEstimate}
                disabled={!description || loadingAi}
                className="flex items-center text-xs text-purple-600 font-medium hover:text-purple-700 transition-colors"
                >
                {loadingAi ? <Loader2 size={14} className="animate-spin mr-1" /> : <Sparkles size={14} className="mr-1" />}
                Assistant IA : Estimer durée & améliorer description
                </button>
            )}
          </div>

          {/* Location with Google Maps */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Lieu</label>
            <div className="relative">
              <input
                type="text"
                required
                value={location}
                onChange={(e) => setLocation(e.target.value)}
                className="w-full pl-10 p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                placeholder="Adresse, quartier ou coordonnées GPS"
              />
              <MapPin size={18} className="absolute left-3 top-3.5 text-gray-400" />
              <button 
                type="button" 
                onClick={handleLocateMe}
                className="absolute right-2 top-2 text-xs bg-gray-100 hover:bg-gray-200 px-2 py-1 rounded text-gray-600 flex items-center transition-colors"
              >
                <MapPin size={12} className="mr-1" /> Ma position
              </button>
            </div>

            <div className="mt-3 rounded-xl overflow-hidden border border-gray-200 shadow-sm bg-gray-50 h-48 relative">
               {location ? (
                 <iframe
                   title="Carte de localisation"
                   width="100%"
                   height="100%"
                   frameBorder="0"
                   scrolling="no"
                   marginHeight={0}
                   marginWidth={0}
                   src={`https://maps.google.com/maps?q=${encodeURIComponent(location)}&t=m&z=15&output=embed&iwloc=near`}
                   className="w-full h-full"
                 ></iframe>
               ) : (
                 <div className="w-full h-full flex flex-col items-center justify-center text-gray-400 bg-gray-50">
                    <MapPin size={32} className="mb-2 opacity-20" />
                    <span className="text-sm">Entrez une adresse pour voir la carte Google Maps</span>
                 </div>
               )}
            </div>
          </div>

          {/* Date & Time Inputs */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Date</label>
              <div className="relative">
                <input
                  type="date"
                  required
                  value={date}
                  onChange={(e) => setDate(e.target.value)}
                  className="w-full pl-10 p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                />
                <Calendar size={18} className="absolute left-3 top-3.5 text-gray-400" />
              </div>
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Heure Début</label>
              <div className="relative">
                <input
                  type="time"
                  required
                  value={startTime}
                  onChange={(e) => setStartTime(e.target.value)}
                  className="w-full pl-10 p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                />
                <Clock size={18} className="absolute left-3 top-3.5 text-gray-400" />
              </div>
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Heure Fin</label>
              <div className="relative">
                <input
                  type="time"
                  required
                  value={endTime}
                  onChange={(e) => setEndTime(e.target.value)}
                  className="w-full pl-10 p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                />
                <Clock size={18} className="absolute left-3 top-3.5 text-gray-400" />
              </div>
            </div>
          </div>

          {/* Duration & Price Preview */}
          <div className="bg-blue-50 p-4 rounded-xl flex justify-between items-center">
            <div>
              <label className="block text-xs font-semibold text-blue-800 uppercase tracking-wide mb-1">
                  {category === ServiceCategory.LAUNDRY ? 'Détail Calcul' : 'Durée calculée'}
              </label>
              <div className="flex items-center space-x-2">
                <span className="font-bold text-lg text-blue-900">
                    {category === ServiceCategory.LAUNDRY 
                        ? `${clothesCount} vêtement${clothesCount > 1 ? 's' : ''}` 
                        : `${duration > 0 ? duration.toFixed(2) : '--'} h`
                    }
                </span>
                {duration <= 0 && (
                   <div className="flex items-center text-red-500 text-xs ml-2">
                      <AlertCircle size={14} className="mr-1" />
                      <span>Horaires invalides</span>
                   </div>
                )}
              </div>
            </div>
            <div className="text-right">
              <div className="text-xs text-blue-600 font-medium mb-1">Prix Total Estimé</div>
              <div className="text-2xl font-bold text-blue-900">{price.toLocaleString()} FCFA</div>
            </div>
          </div>

          {/* Actions */}
          <div className="flex space-x-3 pt-2">
            <button
              type="button"
              onClick={() => setIsCreating(false)}
              className="flex-1 py-3 px-4 rounded-lg text-gray-600 font-medium hover:bg-gray-100 transition-colors"
            >
              Annuler
            </button>
            <button
              type="submit"
              disabled={duration <= 0 || (category === ServiceCategory.LAUNDRY && clothesCount < LAUNDRY_MIN_QTY)}
              className={`flex-1 py-3 px-4 rounded-lg text-white font-bold shadow-lg transition-colors flex justify-center items-center ${
                duration > 0 && (category !== ServiceCategory.LAUNDRY || clothesCount >= LAUNDRY_MIN_QTY)
                ? 'bg-orange-500 hover:bg-orange-600 shadow-orange-200' 
                : 'bg-gray-400 cursor-not-allowed'
              }`}
            >
              Publier la demande
            </button>
          </div>
        </form>
      </div>
    );
  };

  const renderHome = () => (
      <div className="space-y-8 animate-fade-in">
        {/* Header Banner */}
        <div className="bg-gradient-to-r from-blue-600 to-blue-500 rounded-3xl p-8 text-white shadow-lg relative overflow-hidden">
            <div className="relative z-10">
            <h1 className="text-3xl font-bold mb-2">Bonjour, {currentUser.name} 👋</h1>
            <p className="text-blue-100 mb-6 max-w-lg">Trouvez la personne idéale pour votre ménage, cuisine ou petits travaux en quelques clics.</p>
            <button
                onClick={() => setIsCreating(true)}
                className="bg-orange-500 text-white px-6 py-3 rounded-full font-bold shadow-md hover:shadow-xl transform hover:-translate-y-0.5 transition-all flex items-center"
            >
                <Plus size={20} className="mr-2" />
                Nouvelle demande
            </button>
            </div>
            <div className="absolute right-0 bottom-0 opacity-10 transform translate-x-10 translate-y-10">
            <Calculator size={200} />
            </div>
        </div>

        {/* Active Missions List */}
        <div>
            <h2 className="text-xl font-bold text-gray-800 mb-4 flex items-center">
