      setMissions(prev => prev.map(m => m.id === missionId ? { ...m, status: MissionStatus.DISPUTED, disputeReason: reason } : m));

      if (isOfflineMode) {
          alert("Litige signalé (Simulation)");
          return;
      }
      try {
        await updateDoc(doc(db, "missions", missionId), {
            status: MissionStatus.DISPUTED,
            disputeReason: reason,
            disputeInitiator: currentUser.role === UserRole.CLIENT ? 'CLIENT' : 'PROVIDER'
        });
        alert("Litige signalé.");
      } catch (error) {
        // Silent
      }
  };

  const handleRate = async (missionId: string, rating: number, comment: string) => {
      if (!currentUser) return;
      if (isOfflineMode) {
          alert("Note enregistrée (Simulation)");
          return;
      }
      try {
        const updates: any = {};
        if (currentUser.role === UserRole.CLIENT) {
            updates.clientRating = rating;
            updates.clientComment = comment;
        } else {
            updates.providerRating = rating;
            updates.providerComment = comment;
        }
        await updateDoc(doc(db, "missions", missionId), updates);
        alert("Avis enregistré !");
      } catch (error) {
         // Silent
      }
  };

  const handleResolveDispute = async (missionId: string, resolution: 'REFUND' | 'PAY') => {
      if (isOfflineMode) return;
      try {
          const mission = missions.find(m => m.id === missionId);
          const currentReason = mission?.disputeReason || '';
          await updateDoc(doc(db, "missions", missionId), {
              status: resolution === 'PAY' ? MissionStatus.COMPLETED : MissionStatus.CANCELLED,
              disputeReason: currentReason + ` [RESOLU: ${resolution}]`
          });
      } catch (error) {
          // Silent
      }
  };

  const handleVerifyUser = async (userId: string, isVerified: boolean) => {
      if (isOfflineMode) {
          setUsers(prev => prev.map(u => u.id === userId ? {...u, verified: isVerified} : u));
          return;
      }
      try {
        await updateDoc(doc(db, "users", userId), { verified: isVerified });
        alert(isVerified ? "Compte validé." : "Compte bloqué.");
      } catch (error) {
          setUsers(prev => prev.map(u => u.id === userId ? {...u, verified: isVerified} : u));
      }
  };

  const handleUpdateSettings = async (newRates: Record<ServiceCategory, number>, newCommission: number) => {
      if (isOfflineMode) {
          setBaseRates(newRates);
          setCommissionRate(newCommission);
          alert("Paramètres sauvegardés (Local).");
          return;
      }
      try {
        await setDoc(doc(db, "settings", "global"), {
            baseRates: newRates,
            commissionRate: newCommission
        }, { merge: true });
        alert("Paramètres sauvegardés.");
      } catch (error) {
          // Silent
      }
  };

  const handleAddAdmin = async (newAdmin: User) => {
    setUsers(prev => [...prev, newAdmin]);
    if (isOfflineMode) return;
    try {
        await setDoc(doc(db, "users", newAdmin.id), newAdmin);
        alert("Nouvel administrateur ajouté.");
    } catch (error) {
        // Silent
    }
  };

  const handleDeleteUser = async (userId: string) => {
    setUsers(prev => prev.filter(u => u.id !== userId));
    if (isOfflineMode) return;
    if (window.confirm("Voulez-vous vraiment supprimer cet utilisateur ?")) {
        try {
            await deleteDoc(doc(db, "users", userId));
        } catch (error) {
            // Silent
        }
    }
  };

  const resetDemoData = () => {
      if(window.confirm("Réinitialisation locale uniquement.")) {
        localStorage.clear();
        window.location.reload();
      }
  };

  // --- RENDER ---

  if (!currentUser) {
    return (
        <>
            {isOfflineMode && (
                <div className="bg-blue-600 text-white p-2 text-center text-xs font-bold flex items-center justify-center animate-fade-in">
                    <Info size={14} className="mr-2" />
                    Mode Démonstration (Base de données non connectée)
                </div>
            )}
            <Auth users={users} onLogin={handleLogin} onRegister={handleRegister} />
        </>
    );
  }

  return (
    <Layout currentUser={currentUser} onLogout={handleLogout}>
      {isOfflineMode && showOfflineBanner && (
          <div className="bg-blue-50 border border-blue-200 text-blue-800 px-4 py-3 rounded-xl relative mb-6 flex flex-col md:flex-row items-start md:items-center shadow-sm animate-fade-in">
              <div className="flex items-start mb-2 md:mb-0">
                  <Info size={20} className="mr-3 mt-0.5 flex-shrink-0 text-blue-600" />
                  <div>
                      <strong className="font-bold">Mode Démonstration Activé</strong>
                      <p className="text-sm mt-1 text-blue-700">
                          L'application fonctionne avec des données locales simulées car la base de données Firestore n'est pas accessible.
                      </p>
                  </div>
              </div>
              <button 
                onClick={retryConnection}
                className="mt-2 md:mt-0 md:ml-auto flex items-center bg-white border border-blue-200 text-blue-600 px-3 py-1.5 rounded-lg text-xs font-bold hover:bg-blue-50 transition-colors"
              >
                  <RefreshCw size={12} className="mr-1" /> Réessayer la connexion
              </button>
              <button 
                onClick={() => setShowOfflineBanner(false)}
                className="absolute top-2 right-2 text-blue-400 hover:text-blue-600 p-1 md:static md:ml-2"
              >
                  <X size={18} />
              </button>
          </div>
      )}

      <button 
        onClick={resetDemoData}
        className="fixed bottom-2 right-2 text-[10px] text-gray-300 hover:text-red-500 z-50 opacity-50 hover:opacity-100"
      >
        Reset App
      </button>

      {currentUser.role === UserRole.CLIENT && (
        <ClientDashboard 
          currentUser={currentUser} 
          missions={missions} 
          onAddMission={handleAddMission}
          onValidateMission={handleValidateMission}
          onDisputeMission={handleDisputeMission}
          onRateMission={handleRate}
          baseRates={baseRates}
          commissionRate={commissionRate}
          onUpdateUser={handleUpdateUser}
        />
      )}

      {currentUser.role === UserRole.PROVIDER && (
        <ProviderDashboard 
          currentUser={currentUser} 
          missions={missions}
          users={users} 
          onUpdateMissionStatus={handleUpdateMissionStatus}
          onDisputeMission={handleDisputeMission}
          onRateClient={handleRate}
          onUpdateUser={handleUpdateUser}
        />
      )}

      {currentUser.role === UserRole.ADMIN && (
        <AdminDashboard 
          currentUser={currentUser}
          missions={missions}
          users={users}
          baseRates={baseRates}
          commissionRate={commissionRate}
          onResolveDispute={handleResolveDispute}
          onVerifyUser={handleVerifyUser}
          onUpdateSettings={handleUpdateSettings}
          onAddAdmin={handleAddAdmin}
          onDeleteUser={handleDeleteUser}
        />
      )}
    </Layout>
  );
};

export default App;
]]></content>
