<content><![CDATA[
import React, { useState } from 'react';
import { UserRole, User, ServiceCategory } from '../types';
import { Eye, EyeOff, Mail, Lock, Phone, User as UserIcon, CheckCircle, Info, Upload, CreditCard, Camera, AlertCircle, Wrench, Loader2, ArrowLeft, KeyRound, MessageSquare, MapPin } from 'lucide-react';
import { uploadImage, db } from '../services/firebase';
import { doc, updateDoc } from "firebase/firestore";
import { CITIES } from '../constants';

interface AuthProps {
  users: User[];
  onLogin: (user: User) => void;
  onRegister: (newUser: User) => void;
}

// Validation Regex
const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const PHONE_REGEX = /^(\+225)?\s?0[157]\d{8}$|^\d{10}$/;
const NAME_REGEX = /^[a-zA-ZÀ-ÿ\s'-]{3,}$/;
const PASSWORD_REGEX = /^\d{4}$/;

const Auth: React.FC<AuthProps> = ({ users, onLogin, onRegister }) => {
  const [viewMode, setViewMode] = useState<'LOGIN' | 'REGISTER' | 'FORGOT'>('LOGIN');
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [statusMessage, setStatusMessage] = useState('');

  // Form State for Login/Register
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    city: 'Abidjan',
    password: '',
    role: UserRole.CLIENT,
    idNumber: ''
  });

  // Form State for Forgot Password
  const [resetStep, setResetStep] = useState<1 | 2>(1); // 1: Phone, 2: Verify & Reset
  const [resetData, setResetData] = useState({
      phone: '',
      code: '',
      newPassword: ''
  });

  const [selectedServices, setSelectedServices] = useState<ServiceCategory[]>([]);

  // File states
  const [avatarPreview, setAvatarPreview] = useState<string | null>(null);
  const [avatarFile, setAvatarFile] = useState<File | null>(null);
  const [idRectoPreview, setIdRectoPreview] = useState<string | null>(null);
  const [idRectoFile, setIdRectoFile] = useState<File | null>(null);
  const [idVersoPreview, setIdVersoPreview] = useState<string | null>(null);
  const [idVersoFile, setIdVersoFile] = useState<File | null>(null);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    if (e.target.name === 'password') {
        const val = e.target.value;
        if (val && !/^\d*$/.test(val)) return;
        if (val.length > 4) return;
    }
    setFormData({ ...formData, [e.target.name]: e.target.value });
    if (error) setError('');
  };

  const toggleService = (service: ServiceCategory) => {
    if (selectedServices.includes(service)) {
      setSelectedServices(selectedServices.filter(s => s !== service));
    } else {
      setSelectedServices([...selectedServices, service]);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>, type: 'avatar' | 'recto' | 'verso') => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const result = reader.result as string;
        if (type === 'avatar') { setAvatarPreview(result); setAvatarFile(file); }
        if (type === 'recto') { setIdRectoPreview(result); setIdRectoFile(file); }
        if (type === 'verso') { setIdVersoPreview(result); setIdVersoFile(file); }
      };
      reader.readAsDataURL(file);
    }
  };

  const validateRegistration = (): string | null => {
    if (!formData.name.trim()) return "Le nom est obligatoire.";
    if (!NAME_REGEX.test(formData.name.trim())) return "Le nom doit contenir au moins 3 lettres.";
    if (!formData.email.trim()) return "L'email est obligatoire.";
    if (!EMAIL_REGEX.test(formData.email)) return "Adresse email invalide.";
    if (!formData.phone.trim()) return "Le téléphone est obligatoire.";
    if (!PHONE_REGEX.test(formData.phone.replace(/\s/g, ''))) return "Numéro de téléphone invalide.";
    if (!formData.city) return "La ville de résidence est obligatoire.";
    if (!formData.password) return "Le code secret est obligatoire.";
    if (!PASSWORD_REGEX.test(formData.password)) return "Le code secret doit faire 4 chiffres.";
    if (!avatarFile) return "Photo de profil obligatoire.";
    if (!formData.idNumber.trim() || formData.idNumber.length < 5) return "Numéro CNI invalide.";
    if (!idRectoFile) return "Photo CNI Recto obligatoire.";
    if (!idVersoFile) return "Photo CNI Verso obligatoire.";
    if (formData.role === UserRole.PROVIDER && selectedServices.length === 0) {
        return "Veuillez sélectionner au moins une compétence.";
    }
    return null;
  };

  // --- FORGOT PASSWORD HANDLERS ---
  const handleSendResetCode = (e: React.FormEvent) => {
      e.preventDefault();
      setError('');
      const cleanPhone = resetData.phone.replace(/\s/g, '');
      const userExists = users.find(u => u.phone.replace(/\s/g, '') === cleanPhone);

      if (!userExists) {
          // In production we might not want to reveal this, but for this app it's helpful
          setError("Aucun compte associé à ce numéro.");
          return;
      }

      // SIMULATION SMS
      setLoading(true);
      setTimeout(() => {
          setLoading(false);
          alert(`CODE DE RÉINITIALISATION SIMULÉ : 0000`);
          setResetStep(2);
      }, 1500);
  };

  const handleResetConfirm = async (e: React.FormEvent) => {
      e.preventDefault();
      setError('');

      if (resetData.code !== '0000') {
          setError("Code de vérification incorrect.");
          return;
      }
      if (!PASSWORD_REGEX.test(resetData.newPassword)) {
          setError("Le nouveau code doit faire 4 chiffres.");
          return;
      }

      setLoading(true);
      try {
          const cleanPhone = resetData.phone.replace(/\s/g, '');
          const user = users.find(u => u.phone.replace(/\s/g, '') === cleanPhone);

          if (user) {
              // Try firebase update, catch if fails to allow local reset simulation
              try {
                const userRef = doc(db, "users", user.id);
                await updateDoc(userRef, { password: resetData.newPassword });
              } catch (firebaseError) {
                console.warn("Firebase update failed, assuming offline/demo mode", firebaseError);
              }

              alert("Mot de passe modifié avec succès ! Connectez-vous.");
              setViewMode('LOGIN');
              setResetStep(1);
              setResetData({ phone: '', code: '', newPassword: '' });
              setFormData(prev => ({ ...prev, phone: resetData.phone, password: '' }));
          }
      } catch (err) {
          console.error(err);
          setError("Erreur lors de la mise à jour.");
      } finally {
          setLoading(false);
      }
  };

  // --- MAIN AUTH HANDLER ---
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    setStatusMessage('');

    if (viewMode === 'LOGIN') {
        const cleanPhone = formData.phone.replace(/\s/g, '');
        const foundUser = users.find(
          u => u.phone.replace(/\s/g, '') === cleanPhone && u.password === formData.password
        );

        if (foundUser) {
            onLogin(foundUser);
        } else {
            setError("Numéro de téléphone ou code secret incorrect.");
            setLoading(false);
        }
    } else {
        // REGISTER
        const validationError = validateRegistration();
        if (validationError) {
            setError(validationError);
            setLoading(false);
            return;
        }

        try {
            setStatusMessage("Téléchargement des images...");

            // Secure Uploads - Fallback to placeholder if storage fails
            let avatarUrl = "https://picsum.photos/200";
            try {
                if (avatarFile) avatarUrl = await uploadImage(avatarFile, `avatars/${Date.now()}_${avatarFile.name}`);
            } catch (e) {
                console.warn("Avatar upload failed, using placeholder.");
            }

            let idRectoUrl = "placeholder_recto.jpg";
            try {
                if (idRectoFile) idRectoUrl = await uploadImage(idRectoFile, `ids/${Date.now()}_recto_${idRectoFile.name}`);
            } catch (e) {
                console.warn("Recto upload failed, using placeholder.");
            }

            let idVersoUrl = "placeholder_verso.jpg";
            try {
                if (idVersoFile) idVersoUrl = await uploadImage(idVersoFile, `ids/${Date.now()}_verso_${idVersoFile.name}`);
            } catch (e) {
                console.warn("Verso upload failed, using placeholder.");
            }

            const newUser: User = {
                id: `u${Date.now()}`,
                name: formData.name,
                email: formData.email,
                phone: formData.phone,
                password: formData.password,
                city: formData.city,
                role: formData.role,
