                        type="file" 
                        accept="image/*"
                        onChange={handleFileChange}
                        className="absolute inset-0 opacity-0 cursor-pointer"
                      />
                  </div>
                  <span className="text-xs text-gray-500">Cliquez pour changer la photo</span>
              </div>

              <div className="space-y-4">
                  <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Nom Complet</label>
                      <div className="relative">
                          <UserIcon className="absolute left-3 top-3 text-gray-400" size={18} />
                          <input 
                            type="text" 
                            required
                            value={profileForm.name}
                            onChange={(e) => setProfileForm({...profileForm, name: e.target.value})}
                            className="w-full pl-10 p-2.5 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                          />
                      </div>
                  </div>

                  <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Numéro de téléphone</label>
                      <div className="relative">
                          <Phone className="absolute left-3 top-3 text-gray-400" size={18} />
                          <input 
                            type="tel" 
                            required
                            value={profileForm.phone}
                            onChange={(e) => setProfileForm({...profileForm, phone: e.target.value})}
                            className="w-full pl-10 p-2.5 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                          />
                      </div>
                  </div>

                  <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Ville</label>
                      <select
                          value={profileForm.city}
                          onChange={(e) => setProfileForm({...profileForm, city: e.target.value})}
                          className="w-full p-2.5 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                      >
                          {CITIES.map(c => <option key={c} value={c}>{c}</option>)}
                      </select>
                  </div>

                  <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Adresse (Quartier)</label>
                      <div className="relative">
                          <MapPin className="absolute left-3 top-3 text-gray-400" size={18} />
                          <input 
                            type="text" 
                            value={profileForm.address}
                            onChange={(e) => setProfileForm({...profileForm, address: e.target.value})}
                            className="w-full pl-10 p-2.5 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                          />
                      </div>
                  </div>
              </div>

              <button 
                  type="submit"
                  className="w-full bg-blue-600 text-white py-3 rounded-xl font-bold shadow-lg hover:bg-blue-700 transition-all flex items-center justify-center"
              >
                  <Save size={20} className="mr-2" />
                  Enregistrer les modifications
              </button>
          </form>
      </div>
  );

  if (isCreating) return (
      <>
        {renderCreateMission()}
        {renderPaymentModal()}
      </>
  );

  return (
    <div className="space-y-6">
        {renderModal()}
        {renderPaymentModal()}

        {/* Navigation Tabs */}
        <div className="flex justify-center bg-white p-1 rounded-xl shadow-sm max-w-xs mx-auto mb-8">
            <button 
                onClick={() => setActiveTab('HOME')}
                className={`flex-1 py-2 px-4 rounded-lg text-sm font-medium transition-colors ${activeTab === 'HOME' ? 'bg-blue-100 text-blue-700' : 'text-gray-500 hover:bg-gray-50'}`}
            >
                <Home size={16} className="inline mr-2 mb-0.5"/> Accueil
            </button>
            <button 
                onClick={() => setActiveTab('PROFILE')}
                className={`flex-1 py-2 px-4 rounded-lg text-sm font-medium transition-colors ${activeTab === 'PROFILE' ? 'bg-blue-100 text-blue-700' : 'text-gray-500 hover:bg-gray-50'}`}
            >
                <UserIcon size={16} className="inline mr-2 mb-0.5"/> Profil
            </button>
        </div>

        {activeTab === 'HOME' && renderHome()}
        {activeTab === 'PROFILE' && renderProfile()}
    </div>
  );
};

export default ClientDashboard;
]]></content>
</change>

<change>
<file>components/ProviderDashboard.tsx</file>
<description>Filter available missions by user city and allow providers to update their city.</description>
<content><![CDATA[
import React, { useState } from 'react';
import { User, Mission, MissionStatus, ServiceCategory } from '../types';
import { SERVICE_ICONS, CITIES } from '../constants';
import { MapPin, Clock, CheckCircle, AlertTriangle, Star, Calendar, Phone, XCircle, Navigation, Briefcase, User as UserIcon, Camera, Lock, Save, Wallet } from 'lucide-react';

interface ProviderDashboardProps {
  currentUser: User;
  missions: Mission[];
  users: User[]; 
  onUpdateMissionStatus: (
      missionId: string, 
      status: MissionStatus, 
      providerId?: string,
      estimation?: { arrivalTime: string, distance: number }
  ) => void;
  onDisputeMission: (missionId: string, reason: string) => void;
  onRateClient: (missionId: string, rating: number, comment: string) => void;
  onUpdateUser: (data: Partial<User>) => void;
}

const ProviderDashboard: React.FC<ProviderDashboardProps> = ({ 
    currentUser, 
    missions, 
    users,
    onUpdateMissionStatus,
    onDisputeMission,
    onRateClient,
    onUpdateUser
}) => {
  const [activeTab, setActiveTab] = useState<'marketplace' | 'my-missions' | 'wallet' | 'profile'>('marketplace');

  // --- PROFILE EDIT STATE ---
  const [profileForm, setProfileForm] = useState({
    name: currentUser.name,
    phone: currentUser.phone,
    address: currentUser.address || '',
    city: currentUser.city || 'Abidjan',
    password: currentUser.password || ''
  });
  const [selectedServices, setSelectedServices] = useState<ServiceCategory[]>(currentUser.services || []);
  const [newAvatar, setNewAvatar] = useState<string | null>(null);

  // --- MODAL STATES ---
  const [selectedMissionId, setSelectedMissionId] = useState<string | null>(null);
  const [modalType, setModalType] = useState<'DISPUTE' | 'RATING' | null>(null);
  const [inputText, setInputText] = useState('');
  const [ratingValue, setRatingValue] = useState(5);

  // Confirmation State for Mission Acceptance
  const [confirmingMission, setConfirmingMission] = useState<{
      id: string;
      distance: number;
      travelTime: number;
      arrivalTime: Date;
  } | null>(null);

  // Filter missions
  const availableMissions = missions.filter(m => {
      const isPending = m.status === MissionStatus.PENDING && !m.providerId;
      if (!isPending) return false;

      // Filter by City (Location)
      // If provider has a city set, only show missions in that city.
      // If provider has no city set (legacy), show everything (or prompt to update).
      if (currentUser.city && m.city && m.city !== currentUser.city) {
          return false; 
      }

      // Filter by Service Category
      if (currentUser.services && currentUser.services.length > 0) {
          return currentUser.services.includes(m.category);
      }
      return true;
  });

  const myMissions = missions.filter(m => m.providerId === currentUser.id);

  const totalEarnings = myMissions
    .filter(m => m.status === MissionStatus.COMPLETED)
    .reduce((sum, m) => sum + m.providerAmount, 0);

  // Helper to find client details
  const getClient = (clientId: string) => users.find(u => u.id === clientId);

  // --- HANDLERS ---

  const openDispute = (id: string) => {
    setSelectedMissionId(id);
    setModalType('DISPUTE');
    setInputText('');
  };

  const openRating = (id: string) => {
    setSelectedMissionId(id);
    setModalType('RATING');
    setInputText('');
    setRatingValue(5);
  };

  const submitModal = () => {
    if (!selectedMissionId) return;
    if (modalType === 'DISPUTE') {
      onDisputeMission(selectedMissionId, inputText);
    } else if (modalType === 'RATING') {
      onRateClient(selectedMissionId, ratingValue, inputText);
    }
    setModalType(null);
    setSelectedMissionId(null);
  };

  const handleAcceptMission = (missionId: string) => {
    const simulatedDistanceKm = Math.floor(Math.random() * 14) + 1; 
    const averageSpeedKmH = 30; 
    const travelTimeHours = simulatedDistanceKm / averageSpeedKmH;
    const travelTimeMinutes = Math.ceil(travelTimeHours * 60);

    const arrivalTime = new Date();
    arrivalTime.setMinutes(arrivalTime.getMinutes() + travelTimeMinutes);

    setConfirmingMission({
        id: missionId,
        distance: simulatedDistanceKm,
        travelTime: travelTimeMinutes,
        arrivalTime: arrivalTime
    });
  };

  const confirmAcceptance = () => {
      if (!confirmingMission) return;

      onUpdateMissionStatus(
          confirmingMission.id, 
          MissionStatus.ACCEPTED, 
          currentUser.id, 
          { 
              arrivalTime: confirmingMission.arrivalTime.toISOString(), 
              distance: confirmingMission.distance 
          }
      );
      setConfirmingMission(null);
      setActiveTab('my-missions');
  };

  // Profile Handlers
  const handleProfileSubmit = (e: React.FormEvent) => {
      e.preventDefault();
      if (selectedServices.length === 0) {
          alert("Vous devez sélectionner au moins un service !");
          return;
      }
      onUpdateUser({
          name: profileForm.name,
          phone: profileForm.phone,
          address: profileForm.address,
          city: profileForm.city,
          password: profileForm.password,
          services: selectedServices,
          avatarUrl: newAvatar || currentUser.avatarUrl
      });
  };

  const toggleService = (service: ServiceCategory) => {
      if (selectedServices.includes(service)) {
          setSelectedServices(selectedServices.filter(s => s !== service));
      } else {
          setSelectedServices([...selectedServices, service]);
      }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          const reader = new FileReader();
          reader.onloadend = () => {
              setNewAvatar(reader.result as string);
          };
          reader.readAsDataURL(file);
      }
  };

  // --- RENDERERS ---

  const renderConfirmationModal = () => {
      if (!confirmingMission) return null;

      return (
        <div className="fixed inset-0 bg-black bg-opacity-60 flex items-center justify-center z-50 p-4 backdrop-blur-sm">
            <div className="bg-white rounded-2xl p-6 w-full max-w-sm animate-fade-in shadow-2xl">
                <div className="flex items-center justify-center w-12 h-12 bg-blue-100 rounded-full mx-auto mb-4 text-blue-600">
                    <Navigation size={24} />
                </div>
                <h3 className="text-xl font-bold text-center text-gray-900 mb-2">Confirmer le trajet</h3>
                <p className="text-center text-gray-500 text-sm mb-6">
                    Voici l'estimation de votre trajet jusqu'au client. Ces infos lui seront transmises.
                </p>

                <div className="bg-gray-50 rounded-xl p-4 mb-6 space-y-3 border border-gray-100">
                    <div className="flex justify-between items-center">
                        <span className="text-gray-600 text-sm">Distance estimée</span>
                        <span className="font-bold text-gray-900">{confirmingMission.distance} km</span>
                    </div>
                    <div className="flex justify-between items-center">
                        <span className="text-gray-600 text-sm">Temps de trajet</span>
                        <span className="font-bold text-gray-900">{confirmingMission.travelTime} min</span>
                    </div>
                    <div className="border-t border-gray-200 pt-2 flex justify-between items-center">
                        <span className="text-blue-600 font-bold text-sm">Heure d'arrivée</span>
                        <span className="font-bold text-blue-700 text-lg">
                            {confirmingMission.arrivalTime.toLocaleTimeString([], {hour: '2-digit', minute: '2-digit'})}
                        </span>
                    </div>
                </div>

                <div className="flex space-x-3">
                    <button 
                        onClick={() => setConfirmingMission(null)}
                        className="flex-1 py-3 text-gray-600 hover:bg-gray-100 rounded-xl font-medium transition-colors"
                    >
                        Annuler
                    </button>
                    <button 
                        onClick={confirmAcceptance}
                        className="flex-1 py-3 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 shadow-lg shadow-blue-200 transition-colors"
                    >
                        Confirmer
                    </button>
                </div>
            </div>
        </div>
      );
  };

  const renderModal = () => {
    if (!modalType) return null;
    const isDispute = modalType === 'DISPUTE';

    return (
      <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
        <div className="bg-white rounded-2xl p-6 w-full max-w-md animate-fade-in">
          <h3 className={`text-xl font-bold mb-4 ${isDispute ? 'text-red-600' : 'text-blue-600'}`}>
            {isDispute ? 'Signaler un litige' : 'Noter le client'}
          </h3>

          {!isDispute && (
            <div className="flex justify-center space-x-2 mb-4">
              {[1, 2, 3, 4, 5].map((star) => (
                <button
                  key={star}
                  onClick={() => setRatingValue(star)}
                  className={`transition-transform hover:scale-110 ${star <= ratingValue ? 'text-yellow-400' : 'text-gray-300'}`}
                >
                  <Star size={32} fill="currentColor" />
                </button>
              ))}
            </div>
          )}

          <textarea
            value={inputText}
            onChange={(e) => setInputText(e.target.value)}
            className="w-full border border-gray-300 rounded-lg p-3 mb-4 focus:ring-2 focus:ring-blue-500"
            rows={4}
            placeholder={isDispute ? "Décrivez le problème rencontré..." : "Comment s'est passé la mission ?"}
          />

          <div className="flex space-x-3">
            <button 
              onClick={() => setModalType(null)}
              className="flex-1 py-2 text-gray-600 hover:bg-gray-100 rounded-lg"
            >
              Annuler
            </button>
            <button 
              onClick={submitModal}
              disabled={!inputText}
              className={`flex-1 py-2 text-white rounded-lg font-bold ${
                isDispute ? 'bg-red-600 hover:bg-red-700' : 'bg-blue-600 hover:bg-blue-700'
              }`}
            >
              Envoyer
            </button>
          </div>
        </div>
      </div>
    );
  };

  const renderTimeRange = (mission: Mission) => {
    const startDate = new Date(mission.date);
    const endTimeDisplay = mission.endTime 
      ? new Date(mission.endTime).toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' })
      : new Date(startDate.getTime() + mission.durationHours * 3600000).toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' });

    return `${startDate.toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' })} - ${endTimeDisplay}`;
  };

  const renderMarketplace = () => (
    <div className="space-y-4">
      <div className="flex justify-between items-center">
          <h2 className="text-lg font-bold text-gray-800">Propositions de missions</h2>
          <div className="flex space-x-2">
            {currentUser.city && (
                <span className="text-xs bg-blue-100 text-blue-700 px-2 py-1 rounded-full font-medium flex items-center">
                    <MapPin size={10} className="mr-1"/> {currentUser.city}
                </span>
            )}
            {currentUser.services && currentUser.services.length > 0 && (
                <span className="text-xs bg-gray-100 text-gray-600 px-2 py-1 rounded-full font-medium">
                    Mes Compétences
                </span>
            )}
          </div>
      </div>

      {availableMissions.length === 0 ? (
        <div className="text-center py-12 bg-white rounded-2xl border border-dashed border-gray-300">
            <Briefcase size={48} className="mx-auto text-gray-300 mb-3" />
            <p className="text-gray-500 font-medium">Aucune mission correspondante.</p>
            <p className="text-xs text-gray-400 mt-1 max-w-xs mx-auto">
                {currentUser.city 
                 ? `Aucune mission disponible à ${currentUser.city} pour vos compétences.` 
                 : "Veuillez renseigner votre ville dans votre profil pour voir les missions."}
            </p>
        </div>
      ) : (
        availableMissions.map(mission => {
            const Icon = SERVICE_ICONS[mission.category];
            return (
            <div key={mission.id} className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
                <div className="flex items-start justify-between">
                <div className="flex items-center space-x-3">
                    <div className="p-3 bg-blue-50 text-blue-600 rounded-xl">
                    <Icon size={24} />
                    </div>
                    <div>
                    <h3 className="font-bold text-gray-900">{mission.title}</h3>
                    <div className="flex items-center text-sm text-gray-500 mt-1">
                        <MapPin size={14} className="mr-1" /> {mission.location} <span className="text-xs bg-gray-100 px-1 rounded ml-1">{mission.city}</span>
                    </div>
                    </div>
                </div>
                <div className="text-right">
                    <div className="text-xl font-bold text-green-600">{mission.providerAmount.toLocaleString()} FCFA</div>
                    <div className="text-xs text-gray-400">Net vendeur</div>
                </div>
                </div>

                <div className="mt-4 grid grid-cols-2 gap-4 text-sm text-gray-600 bg-gray-50 p-3 rounded-lg">
                <div className="flex items-center">
                    <Clock size={16} className="mr-2" /> 
                    <span className="font-medium">{renderTimeRange(mission)}</span>
                </div>
                <div className="flex items-center">
                    <Calendar size={16} className="mr-2" /> 
                    {new Date(mission.date).toLocaleDateString('fr-FR', {day: 'numeric', month: 'short'})}
                </div>
                </div>

                <p className="mt-4 text-gray-600 text-sm">{mission.description}</p>

                <div className="mt-6">
                <button 
                    onClick={() => handleAcceptMission(mission.id)}
                    className="w-full bg-blue-600 text-white py-3 rounded-xl font-bold hover:bg-blue-700 transition-colors shadow-lg shadow-blue-200"
                >
                    Accepter la mission
                </button>
                </div>
            </div>
            )
        })
      )}
    </div>
  );

  const renderMyMissions = () => (
    <div className="space-y-4">
      {myMissions.map(mission => {
        const client = getClient(mission.clientId);
        return (
        <div key={mission.id} className="bg-white p-6 rounded-2xl shadow-sm border-l-4 border-blue-500 relative">
          {(mission.status === MissionStatus.IN_PROGRESS || mission.status === MissionStatus.ACCEPTED) && (
              <button 
                onClick={() => openDispute(mission.id)}
                className="absolute top-4 right-4 text-red-400 hover:text-red-600 p-2"
                title="Signaler un litige"
              >
                  <AlertTriangle size={20} />
              </button>
          )}

          <div className="flex justify-between mb-2 pr-8">
            <h3 className="font-bold text-gray-900">{mission.title}</h3>
            <span className={`text-xs px-2 py-1 rounded-full font-bold ${
                mission.status === MissionStatus.DISPUTED ? 'bg-red-100 text-red-800' : 
                mission.status === MissionStatus.PAYMENT_PENDING ? 'bg-green-100 text-green-800' :
                'bg-blue-100 text-blue-800'
            }`}>
                {mission.status}
            </span>
          </div>

          <div className="flex items-center text-xs text-gray-500 mb-4">
             <Clock size={12} className="mr-1" /> {renderTimeRange(mission)}
          </div>

          {client && (
              <div className="bg-gray-50 p-4 rounded-xl border border-gray-100 mb-4">
                 <div className="flex items-center justify-between">
                    <div className="flex items-center space-x-3">
                        <img src={client.avatarUrl} alt={client.name} className="w-10 h-10 rounded-full border border-white shadow-sm object-cover" />
                        <div>
                            <p className="text-xs text-gray-500 font-medium">Client</p>
                            <p className="text-sm font-bold text-gray-900">{client.name}</p>
                        </div>
                    </div>
                    <div className="flex space-x-2">
                        <a 
                           href={`tel:${client.phone}`} 
                           className="p-2 bg-green-100 text-green-600 rounded-full hover:bg-green-200 transition-colors"
                           title="Appeler le client"
                        >
                            <Phone size={18} />
                        </a>
                        <a 
                           href={`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(mission.location)}`}
                           target="_blank"
                           rel="noreferrer" 
                           className="p-2 bg-blue-100 text-blue-600 rounded-full hover:bg-blue-200 transition-colors"
                           title="Voir sur Maps"
                        >
                            <Navigation size={18} />
                        </a>
                    </div>
                 </div>
              </div>
          )}

          <div className="space-y-3">
            {mission.status === MissionStatus.ACCEPTED && (
                <div className="grid grid-cols-2 gap-3">
                    <button 
                        onClick={() => onUpdateMissionStatus(mission.id, MissionStatus.PENDING)}
                        className="flex items-center justify-center border border-gray-300 text-gray-500 py-2 rounded-lg font-medium hover:bg-gray-100 hover:text-gray-700"
                    >
                        <XCircle size={16} className="mr-2" /> Annuler
                    </button>
                    <button 
                        onClick={() => onUpdateMissionStatus(mission.id, MissionStatus.IN_PROGRESS)}
                        className="bg-blue-600 text-white py-2 rounded-lg font-bold hover:bg-blue-700 shadow-sm"
                    >
                        Commencer
                    </button>
                </div>
            )}

            {mission.status === MissionStatus.IN_PROGRESS && (
                <button 
                    onClick={() => onUpdateMissionStatus(mission.id, MissionStatus.PAYMENT_PENDING)}
                    className="w-full bg-green-600 text-white py-2 rounded-lg font-bold hover:bg-green-700 shadow-sm flex items-center justify-center"
                >
                    <CheckCircle size={16} className="mr-2" /> Terminer la mission
                </button>
            )}

            {mission.status === MissionStatus.PAYMENT_PENDING && (
                <div className="bg-yellow-50 p-3 rounded-lg border border-yellow-100 text-sm text-yellow-800 flex items-center justify-center">
                    <Clock size={16} className="mr-2" />
                    Attente paiement client...
                </div>
            )}

            {mission.status === MissionStatus.COMPLETED && !mission.providerRating && (
                <button 
                    onClick={() => openRating(mission.id)}
                    className="w-full bg-yellow-50 text-yellow-700 py-2 rounded-lg font-medium hover:bg-yellow-100 flex justify-center items-center"
                >
                    <Star size={16} className="mr-2" /> Noter le client
                </button>
            )}

            {mission.status === MissionStatus.COMPLETED && mission.providerRating && (
                 <div className="text-center text-sm text-green-600 font-medium flex justify-center items-center bg-green-50 p-2 rounded-lg">
                    <CheckCircle size={14} className="mr-1" /> Mission terminée & notée
                </div>
            )}

            {mission.status === MissionStatus.DISPUTED && (
                <div className="bg-red-50 p-3 rounded-lg text-sm text-red-700">
                    Dossier en cours d'analyse par l'administrateur.
                </div>
            )}
          </div>
        </div>
      )})
      }
      {myMissions.length === 0 && <p className="text-gray-500">Vous n'avez aucune mission en cours.</p>}
    </div>
  );

  const renderWallet = () => (
    <div className="space-y-6">
        <div className="bg-gradient-to-br from-gray-900 to-gray-800 rounded-2xl p-8 text-white shadow-xl">
            <p className="text-gray-400 text-sm mb-1">Solde disponible</p>
            <h2 className="text-4xl font-bold mb-6">{(currentUser.walletBalance || 0 + totalEarnings).toLocaleString()} FCFA</h2>
            <div className="flex space-x-4">
                <button className="flex-1 bg-white/10 hover:bg-white/20 py-2 rounded-lg text-sm font-medium backdrop-blur-sm transition-colors">
                    Retrait Mobile Money
                </button>
                <button className="flex-1 bg-white/10 hover:bg-white/20 py-2 rounded-lg text-sm font-medium backdrop-blur-sm transition-colors">
                    Virement
                </button>
            </div>
        </div>

        <div>
            <h3 className="font-bold text-gray-800 mb-3">Historique récent</h3>
            <div className="bg-white rounded-xl shadow-sm overflow-hidden">
                {myMissions.filter(m => m.status === MissionStatus.COMPLETED).map(m => (
                    <div key={m.id} className="p-4 border-b border-gray-100 flex justify-between items-center last:border-0">
                        <div>
                            <p className="font-medium text-gray-900">{m.title}</p>
                            <p className="text-xs text-gray-500">{new Date(m.date).toLocaleDateString()}</p>
                        </div>
                        <span className="text-green-600 font-bold">+{m.providerAmount} FCFA</span>
                    </div>
