import React, { useState, useEffect, useRef } from 'react';
import { UserRole, User, Mission, MissionStatus, ServiceCategory } from './types';
import { BASE_RATES, COMMISSION_RATE, MOCK_USERS, MOCK_MISSIONS } from './constants';
import Auth from './components/Auth';
import Layout from './components/Layout';
import ClientDashboard from './components/ClientDashboard';
import ProviderDashboard from './components/ProviderDashboard';
import AdminDashboard from './components/AdminDashboard';
import { X, Info, RefreshCw } from 'lucide-react';

// Firebase Imports
import { db } from './services/firebase';
import { collection, onSnapshot, doc, updateDoc, setDoc, query, orderBy, deleteDoc, disableNetwork, getDoc } from "firebase/firestore";

const App: React.FC = () => {
  // --- STATE ---

  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('serviplus_current_user');
    try {
        return saved ? JSON.parse(saved) : null;
    } catch (e) {
        return null;
    }
  });

  // Initialize with MOCK data immediately to avoid empty screens while connecting
  const [users, setUsers] = useState<User[]>(MOCK_USERS);
  const [missions, setMissions] = useState<Mission[]>(MOCK_MISSIONS);

  const [baseRates, setBaseRates] = useState<Record<ServiceCategory, number>>(BASE_RATES);
  const [commissionRate, setCommissionRate] = useState<number>(COMMISSION_RATE);

  // Error Handling State - Persistent
  const [isOfflineMode, setIsOfflineMode] = useState(() => {
      return localStorage.getItem('serviplus_offline_mode') === 'true';
  });

  // Gating state: Only start main listeners if we have verified connectivity
  const [isConnectionVerified, setIsConnectionVerified] = useState(false);

  const [showOfflineBanner, setShowOfflineBanner] = useState(true);

  // Ref to track offline status synchronously across multiple effects
  const isOfflineRef = useRef(isOfflineMode);

  const enableOfflineMode = async () => {
      if (isOfflineRef.current) return; // Already handled
      console.log("Firebase unavailable. Switching to Offline Demo Mode.");
      isOfflineRef.current = true;
      setIsOfflineMode(true);
      localStorage.setItem('serviplus_offline_mode', 'true');

      try {
          await disableNetwork(db);
      } catch (e) {
          console.warn("Failed to disable network:", e);
      }
  };

  const retryConnection = () => {
      localStorage.removeItem('serviplus_offline_mode');
      window.location.reload();
  };

  // --- HELPER: Sanitize Data ---
  const sanitizeData = (data: any): any => {
      return JSON.parse(JSON.stringify(data, (key, value) => {
          if (value === undefined) return null;
          return value;
      }));
  };

  // --- FIREBASE CONNECTION LOGIC ---

  // 1. Force disable network immediately if we know we are offline (prevents errors on reload)
  useEffect(() => {
      if (isOfflineMode) {
          disableNetwork(db).catch(() => {});
      }
  }, [isOfflineMode]);

  // 2. Connection Probe: Try one lightweight request before starting all listeners
  useEffect(() => {
      if (isOfflineMode) return;

      const verifyConnection = async () => {
          try {
              // Try to fetch a dummy doc. If API is disabled, this throws immediately.
              // We don't care about the result, just that it doesn't throw a permission error.
              await getDoc(doc(db, "settings", "probe"));
              setIsConnectionVerified(true);
          } catch (error: any) {
              if (error.code === 'permission-denied' || error.code === 'unavailable' || error.code === 'failed-precondition') {
                  enableOfflineMode();
              } else {
                  // Other errors (like 'not-found') mean the connection is actually working!
                  setIsConnectionVerified(true);
              }
          }
      };

      verifyConnection();
  }, []); // Run once on mount

  // --- DATA LISTENERS (Gated by isConnectionVerified) ---

  // Sync Users
  useEffect(() => {
    if (isOfflineMode || !isConnectionVerified || isOfflineRef.current) return;

    let unsubscribe = () => {};
    try {
        unsubscribe = onSnapshot(collection(db, "users"), (snapshot) => {
            const loadedUsers = snapshot.docs.map(doc => {
                return { ...doc.data(), id: doc.id } as User;
            });
            setUsers(loadedUsers.length > 0 ? loadedUsers : MOCK_USERS);
        }, (error) => {
            if (error.code === 'permission-denied' || error.code === 'unavailable') {
                enableOfflineMode();
            }
        });
    } catch (err) {
        enableOfflineMode();
    }
    return () => unsubscribe();
  }, [isOfflineMode, isConnectionVerified]);

  // Sync Missions
  useEffect(() => {
    if (isOfflineMode || !isConnectionVerified || isOfflineRef.current) return;

    let unsubscribe = () => {};
    try {
        const q = query(collection(db, "missions"), orderBy("createdAt", "desc"));
        unsubscribe = onSnapshot(q, (snapshot) => {
            const loadedMissions = snapshot.docs.map(doc => {
                return { ...doc.data(), id: doc.id } as Mission;
            });
            setMissions(loadedMissions);
        }, (error) => {
            if (error.code === 'permission-denied' || error.code === 'unavailable') {
                enableOfflineMode();
            }
        });
    } catch (err) {
        enableOfflineMode();
    }
    return () => unsubscribe();
  }, [isOfflineMode, isConnectionVerified]);

  // Sync Settings
  useEffect(() => {
    if (isOfflineMode || !isConnectionVerified || isOfflineRef.current) return;

    let unsubscribe = () => {};
    try {
        unsubscribe = onSnapshot(doc(db, "settings", "global"), (doc) => {
            if (doc.exists()) {
                const data = doc.data();
                if (data.baseRates) setBaseRates(data.baseRates);
                if (data.commissionRate) setCommissionRate(data.commissionRate);
            }
        }, (error) => {
             // Just ignore settings errors
        });
    } catch (err) {
        // Ignore
    }
    return () => unsubscribe();
  }, [isOfflineMode, isConnectionVerified]);

  // Persist current session locally
  useEffect(() => {
    if (currentUser) {
      try {
        const safeUser = sanitizeData(currentUser);
        const freshUser = users.find(u => u.id === currentUser.id);
        if (freshUser) {
             const safeFreshUser = sanitizeData(freshUser);
             if (JSON.stringify(safeFreshUser) !== JSON.stringify(safeUser)) {
                 setCurrentUser(freshUser);
                 localStorage.setItem('serviplus_current_user', JSON.stringify(safeFreshUser));
             } else {
                 localStorage.setItem('serviplus_current_user', JSON.stringify(safeUser));
             }
        } else {
             localStorage.setItem('serviplus_current_user', JSON.stringify(safeUser));
        }
      } catch (e) {
          // Ignore persistence errors
      }
    } else {
      localStorage.removeItem('serviplus_current_user');
    }
  }, [currentUser, users]);


  // --- HANDLERS ---

  const handleLogin = (user: User) => {
    setCurrentUser(user);
  };

  const handleRegister = async (newUser: User) => {
    setCurrentUser(newUser);
    setUsers(prev => [...prev, newUser]);

    if (isOfflineMode) return;

    try {
        const safeUser = sanitizeData(newUser);
        await setDoc(doc(db, "users", newUser.id), safeUser);
        alert(`Bienvenue ${newUser.name} !`);
    } catch (error: any) {
        enableOfflineMode();
    }
  };

  const handleLogout = () => {
    setCurrentUser(null);
  };

  const handleUpdateUser = async (updatedData: Partial<User>) => {
    if (!currentUser) return;

    const updatedUser = { ...currentUser, ...updatedData };
    setUsers(prev => prev.map(u => u.id === currentUser.id ? updatedUser : u));
    setCurrentUser(updatedUser);

    if (isOfflineMode) {
        alert("Profil mis à jour (Local)");
        return;
    }
    try {
        await updateDoc(doc(db, "users", currentUser.id), updatedData);
        alert("Profil mis à jour !");
    } catch (error) {
        // Silent fallback
    }
  };

  const handleAddMission = async (newMission: Mission) => {
    setMissions(prev => [newMission, ...prev]);

    if (isOfflineMode) {
        alert("Mission publiée (Mode Démo)");
        return;
    }
    try {
        const missionData: any = { ...newMission };
        // Handle potential undefineds
        if (missionData.quantity === undefined) missionData.quantity = null;
        if (missionData.providerId === undefined) missionData.providerId = null;
        if (missionData.providerName === undefined) missionData.providerName = null;
        if (missionData.endTime === undefined) missionData.endTime = null;

        await setDoc(doc(db, "missions", newMission.id), missionData);
        alert(`Mission publiée !`);
    } catch (error) {
        enableOfflineMode();
        alert("Mission publiée (Mode hors ligne)");
    }
  };

  const handleUpdateMissionStatus = async (
    missionId: string, 
    status: MissionStatus, 
    providerId?: string,
    estimation?: { arrivalTime: string, distance: number }
  ) => {
    setMissions(prev => prev.map(m => {
        if (m.id !== missionId) return m;
        const updated = { ...m, status };
        if (status === MissionStatus.PENDING) {
            updated.providerId = undefined;
            updated.providerName = undefined;
        } else if (providerId) {
            updated.providerId = providerId;
            const p = users.find(u => u.id === providerId);
            if (p) updated.providerName = p.name;
        }
        if (estimation) {
            updated.estimatedArrivalTime = estimation.arrivalTime;
            updated.estimatedDistance = estimation.distance;
        }
        return updated;
    }));

    if (isOfflineMode) return;

    try {
        const missionRef = doc(db, "missions", missionId);
        const updates: any = { status };

        if (status === MissionStatus.PENDING) {
             updates.providerId = null;
             updates.providerName = null;
             updates.estimatedArrivalTime = null;
             updates.estimatedDistance = null;
        } else if (providerId) {
            updates.providerId = providerId;
            const provider = users.find(u => u.id === providerId);
            if (provider) updates.providerName = provider.name;
        }

        if (estimation) {
            updates.estimatedArrivalTime = estimation.arrivalTime;
            updates.estimatedDistance = estimation.distance;
        }

        await updateDoc(missionRef, updates);
    } catch (error) {
        // Silent
    }
  };

  const handleValidateMission = async (missionId: string) => {
    setMissions(prev => prev.map(m => m.id === missionId ? { ...m, status: MissionStatus.COMPLETED } : m));

    if (isOfflineMode) {
        alert("Mission validée (Mode Démo)");
        return;
    }
    try {
        await updateDoc(doc(db, "missions", missionId), {
            status: MissionStatus.COMPLETED,
            completedAt: new Date().toISOString()
        });
        alert("Mission validée ! Paiement débloqué.");
    } catch (error) {
        // Silent
    }
  };

  const handleDisputeMission = async (missionId: string, reason: string) => {
      if (!currentUser) return;
      setMissions(prev => prev.map(m => m.id === missionId ? { ...m, status: MissionStatus.DISPUTED, disputeReason: reason } : m));

      if (isOfflineMode) {
          alert("Litige signalé (Simulation)");
          return;
      }
      try {
        await updateDoc(doc(db, "missions", missionId), {
            status: MissionStatus.DISPUTED,
            disputeReason: reason,
            disputeInitiator: currentUser.role === UserRole.CLIENT ? 'CLIENT' : 'PROVIDER'
        });
        alert("Litige signalé.");
      } catch (error) {
        // Silent
      }
  };

  const handleRate = async (missionId: string, rating: number, comment: string) => {
      if (!currentUser) return;
      if (isOfflineMode) {
          alert("Note enregistrée (Simulation)");
          return;
      }
      try {
        const updates: any = {};
        if (currentUser.role === UserRole.CLIENT) {
            updates.clientRating = rating;
            updates.clientComment = comment;
        } else {
            updates.providerRating = rating;
            updates.providerComment = comment;
        }
        await updateDoc(doc(db, "missions", missionId), updates);
        alert("Avis enregistré !");
      } catch (error) {
         // Silent
      }
  };

  const handleResolveDispute = async (missionId: string, resolution: 'REFUND' | 'PAY') => {
      if (isOfflineMode) return;
      try {
          const mission = missions.find(m => m.id === missionId);
          const currentReason = mission?.disputeReason || '';
          await updateDoc(doc(db, "missions", missionId), {
              status: resolution === 'PAY' ? MissionStatus.COMPLETED : MissionStatus.CANCELLED,
              disputeReason: currentReason + ` [RESOLU: ${resolution}]`
          });
      } catch (error) {
          // Silent
      }
  };

  const handleVerifyUser = async (userId: string, isVerified: boolean) => {
      if (isOfflineMode) {
          setUsers(prev => prev.map(u => u.id === userId ? {...u, verified: isVerified} : u));
          return;
      }
      try {
        await updateDoc(doc(db, "users", userId), { verified: isVerified });
        alert(isVerified ? "Compte validé." : "Compte bloqué.");
      } catch (error) {
          setUsers(prev => prev.map(u => u.id === userId ? {...u, verified: isVerified} : u));
      }
  };

  const handleUpdateSettings = async (newRates: Record<ServiceCategory, number>, newCommission: number) => {
      if (isOfflineMode) {
          setBaseRates(newRates);
          setCommissionRate(newCommission);
          alert("Paramètres sauvegardés (Local).");
          return;
      }
      try {
        await setDoc(doc(db, "settings", "global"), {
            baseRates: newRates,
            commissionRate: newCommission
        }, { merge: true });
        alert("Paramètres sauvegardés.");
      } catch (error) {
          // Silent
      }
  };

  const handleAddAdmin = async (newAdmin: User) => {
    setUsers(prev => [...prev, newAdmin]);
    if (isOfflineMode) return;
    try {
        await setDoc(doc(db, "users", newAdmin.id), newAdmin);
        alert("Nouvel administrateur ajouté.");
    } catch (error) {
        // Silent
    }
  };

  const handleDeleteUser = async (userId: string) => {
    setUsers(prev => prev.filter(u => u.id !== userId));
    if (isOfflineMode) return;
    if (window.confirm("Voulez-vous vraiment supprimer cet utilisateur ?")) {
        try {
            await deleteDoc(doc(db, "users", userId));
        } catch (error) {
            // Silent
        }
    }
  };

  const resetDemoData = () => {
      if(window.confirm("Réinitialisation locale uniquement.")) {
        localStorage.clear();
        window.location.reload();
      }
  };

  // --- RENDER ---

  if (!currentUser) {
    return (
        <>
            {isOfflineMode && (
                <div className="bg-blue-600 text-white p-2 text-center text-xs font-bold flex items-center justify-center animate-fade-in">
                    <Info size={14} className="mr-2" />
                    Mode Démonstration (Base de données non connectée)
                </div>
            )}
            <Auth users={users} onLogin={handleLogin} onRegister={handleRegister} />
        </>
    );
  }

  return (
    <Layout currentUser={currentUser} onLogout={handleLogout}>
      {isOfflineMode && showOfflineBanner && (
          <div className="bg-blue-50 border border-blue-200 text-blue-800 px-4 py-3 rounded-xl relative mb-6 flex flex-col md:flex-row items-start md:items-center shadow-sm animate-fade-in">
              <div className="flex items-start mb-2 md:mb-0">
                  <Info size={20} className="mr-3 mt-0.5 flex-shrink-0 text-blue-600" />
                  <div>
                      <strong className="font-bold">Mode Démonstration Activé</strong>
                      <p className="text-sm mt-1 text-blue-700">
                          L'application fonctionne avec des données locales simulées car la base de données Firestore n'est pas accessible.
                      </p>
                  </div>
              </div>
              <button 
                onClick={retryConnection}
                className="mt-2 md:mt-0 md:ml-auto flex items-center bg-white border border-blue-200 text-blue-600 px-3 py-1.5 rounded-lg text-xs font-bold hover:bg-blue-50 transition-colors"
              >
                  <RefreshCw size={12} className="mr-1" /> Réessayer la connexion
              </button>
              <button 
                onClick={() => setShowOfflineBanner(false)}
                className="absolute top-2 right-2 text-blue-400 hover:text-blue-600 p-1 md:static md:ml-2"
              >
                  <X size={18} />
              </button>
          </div>
      )}

      <button 
        onClick={resetDemoData}
        className="fixed bottom-2 right-2 text-[10px] text-gray-300 hover:text-red-500 z-50 opacity-50 hover:opacity-100"
      >
        Reset App
      </button>

      {currentUser.role === UserRole.CLIENT && (
        <ClientDashboard 
          currentUser={currentUser} 
          missions={missions} 
          onAddMission={handleAddMission}
          onValidateMission={handleValidateMission}
          onDisputeMission={handleDisputeMission}
          onRateMission={handleRate}
          baseRates={baseRates}
          commissionRate={commissionRate}
          onUpdateUser={handleUpdateUser}
        />
      )}

      {currentUser.role === UserRole.PROVIDER && (
        <ProviderDashboard 
          currentUser={currentUser} 
          missions={missions}
          users={users} 
          onUpdateMissionStatus={handleUpdateMissionStatus}
          onDisputeMission={handleDisputeMission}
          onRateClient={handleRate}
          onUpdateUser={handleUpdateUser}
        />
      )}

      {currentUser.role === UserRole.ADMIN && (
        <AdminDashboard 
          currentUser={currentUser}
          missions={missions}
          users={users}
          baseRates={baseRates}
          commissionRate={commissionRate}
          onResolveDispute={handleResolveDispute}
          onVerifyUser={handleVerifyUser}
          onUpdateSettings={handleUpdateSettings}
          onAddAdmin={handleAddAdmin}
          onDeleteUser={handleDeleteUser}
        />
      )}
    </Layout>
  );
};

export default App;
