                  <span className="text-xs font-medium text-center">{cat}</span>
                </button>
              );
            })}
          </div>

          {/* --- MARKET SPECIFIC FORM --- */}
          {category === ServiceCategory.MARKET && (
              <div className="bg-orange-50 p-5 rounded-xl border border-orange-100">
                  <h3 className="font-bold text-orange-800 mb-4 flex items-center">
                      <ShoppingBasket size={20} className="mr-2"/>
                      Ma liste de courses
                  </h3>

                  <div className="space-y-3 mb-4">
                      {marketItems.map((item, index) => (
                          <div key={index} className="flex space-x-2">
                              <input 
                                type="text" 
                                placeholder="Nom de l'ingrédient (ex: 1kg Tomate)"
                                className="flex-1 p-2 border border-orange-200 rounded-lg text-sm focus:ring-orange-500 focus:border-orange-500"
                                value={item.name}
                                onChange={(e) => updateMarketItem(index, 'name', e.target.value)}
                                required
                              />
                              <input 
                                type="number" 
                                placeholder="Prix estimé"
                                className="w-24 p-2 border border-orange-200 rounded-lg text-sm focus:ring-orange-500 focus:border-orange-500"
                                value={item.price || ''}
                                onChange={(e) => updateMarketItem(index, 'price', parseInt(e.target.value))}
                                required
                              />
                              {marketItems.length > 1 && (
                                  <button 
                                    type="button"
                                    onClick={() => removeMarketItem(index)}
                                    className="p-2 text-red-400 hover:text-red-600 hover:bg-red-50 rounded-lg"
                                  >
                                      <Trash2 size={18}/>
                                  </button>
                              )}
                          </div>
                      ))}
                  </div>

                  <button 
                    type="button"
                    onClick={addMarketItem}
                    className="text-sm font-bold text-orange-600 hover:text-orange-700 flex items-center mb-6"
                  >
                      <Plus size={16} className="mr-1"/> Ajouter un ingrédient
                  </button>

                  <div className="bg-white p-4 rounded-lg border border-orange-200 space-y-2 text-sm">
                      <div className="flex justify-between text-gray-600">
                          <span>Total Ingrédients</span>
                          <span>{marketItems.reduce((sum, i) => sum + (i.price || 0), 0).toLocaleString()} FCFA</span>
                      </div>
                      <div className="flex justify-between text-gray-600">
                          <span>Frais Emballage (Imposé)</span>
                          <span>{MARKET_PACKAGING_FEE} FCFA</span>
                      </div>
                      <div className="flex justify-between text-gray-600">
                          <span>Frais Course (Main d'œuvre)</span>
                          <span>{MARKET_SERVICE_FEE} FCFA</span>
                      </div>
                      <div className="flex justify-between text-gray-600">
                          <span>Frais Livraison (Standard)</span>
                          <span>{MARKET_DELIVERY_FEE} FCFA</span>
                      </div>
                      <div className="border-t border-orange-100 pt-2 flex justify-between font-bold text-orange-800 text-lg">
                          <span>Total à Payer</span>
                          <span>{calculatePrice().toLocaleString()} FCFA</span>
                      </div>
                  </div>

                  <div className="mt-4 flex items-start bg-blue-50 p-3 rounded-lg text-blue-800 text-xs">
                      <Info size={16} className="mr-2 mt-0.5 flex-shrink-0"/>
                      <div>
                          <strong>Créneau de livraison automatique :</strong><br/>
                          {deliveryWindow}
                      </div>
                  </div>
              </div>
          )}

          {/* Special Laundry Input */}
          {category === ServiceCategory.LAUNDRY && (
             <div className="bg-blue-50 p-4 rounded-xl border border-blue-100">
                <label className="block text-sm font-bold text-blue-900 mb-2 flex items-center">
                    <Shirt size={18} className="mr-2" />
                    Nombre de vêtements à laver
                </label>
                <div className="space-y-2">
                    <input
                        type="number"
                        min={LAUNDRY_MIN_QTY}
                        value={clothesCount}
                        onChange={(e) => setClothesCount(parseInt(e.target.value) || LAUNDRY_MIN_QTY)}
                        className="w-full p-3 border border-blue-300 rounded-lg focus:ring-2 focus:ring-blue-500 text-lg font-bold text-center"
                    />
                    <p className="text-xs text-blue-600 text-center">
                        Minimum {LAUNDRY_MIN_QTY} vêtements ({LAUNDRY_MIN_PRICE} FCFA) <br/>
                        + {LAUNDRY_EXTRA_PRICE} FCFA par vêtement supplémentaire.
                    </p>
                </div>
             </div>
          )}

          {/* Description with AI (Hide for Market) */}
          {category !== ServiceCategory.MARKET && (
          <div className="space-y-2">
            <label className="block text-sm font-medium text-gray-700">Description du besoin</label>
            <textarea
              required
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              rows={3}
              placeholder="Ex: J'ai besoin d'un nettoyage complet..."
            />
            {category !== ServiceCategory.LAUNDRY && (
                <button
                type="button"
                onClick={handleAiEstimate}
                disabled={!description || loadingAi}
                className="flex items-center text-xs text-purple-600 font-medium hover:text-purple-700 transition-colors"
                >
                {loadingAi ? <Loader2 size={14} className="animate-spin mr-1" /> : <Sparkles size={14} className="mr-1" />}
                Assistant IA : Estimer durée & améliorer description
                </button>
            )}
          </div>
          )}

          {/* Location with Google Maps */}
          <div className="space-y-2">
            <label className="block text-sm font-medium text-gray-700">Ville</label>
            <select
                value={city}
                onChange={(e) => setCity(e.target.value)}
                className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
            >
                {CITIES.map(c => <option key={c} value={c}>{c}</option>)}
            </select>
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Adresse Précise / Quartier</label>
            <div className="relative">
              <input
                type="text"
                required
                value={location}
                onChange={(e) => setLocation(e.target.value)}
                className="w-full pl-10 p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                placeholder="Ex: Riviera 2, Rue des jardins"
              />
              <MapPin size={18} className="absolute left-3 top-3.5 text-gray-400" />
              <button 
                type="button" 
                onClick={handleLocateMe}
                className="absolute right-2 top-2 text-xs bg-gray-100 hover:bg-gray-200 px-2 py-1 rounded text-gray-600 flex items-center transition-colors"
              >
                <MapPin size={12} className="mr-1" /> Ma position
              </button>
            </div>

            <div className="mt-3 rounded-xl overflow-hidden border border-gray-200 shadow-sm bg-gray-50 h-48 relative">
               {location ? (
                 <iframe
                   title="Carte de localisation"
                   width="100%"
                   height="100%"
                   frameBorder="0"
                   scrolling="no"
                   marginHeight={0}
                   marginWidth={0}
                   src={`https://maps.google.com/maps?q=${encodeURIComponent(city + ", " + location)}&t=m&z=15&output=embed&iwloc=near`}
                   className="w-full h-full"
                 ></iframe>
               ) : (
                 <div className="w-full h-full flex flex-col items-center justify-center text-gray-400 bg-gray-50">
                    <MapPin size={32} className="mb-2 opacity-20" />
                    <span className="text-sm">Entrez une adresse pour voir la carte Google Maps</span>
                 </div>
               )}
            </div>
          </div>

          {/* Date & Time Inputs (Hide for Market) */}
          {category !== ServiceCategory.MARKET && (
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Date</label>
              <div className="relative">
                <input
                  type="date"
                  required
                  value={date}
                  onChange={(e) => setDate(e.target.value)}
                  className="w-full pl-10 p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                />
                <Calendar size={18} className="absolute left-3 top-3.5 text-gray-400" />
              </div>
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Heure Début</label>
              <div className="relative">
                <input
                  type="time"
                  required
                  value={startTime}
                  onChange={(e) => setStartTime(e.target.value)}
                  className="w-full pl-10 p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                />
                <Clock size={18} className="absolute left-3 top-3.5 text-gray-400" />
              </div>
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Heure Fin</label>
              <div className="relative">
                <input
                  type="time"
                  required
                  value={endTime}
                  onChange={(e) => setEndTime(e.target.value)}
                  className="w-full pl-10 p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                />
                <Clock size={18} className="absolute left-3 top-3.5 text-gray-400" />
              </div>
            </div>
          </div>
          )}

          {/* Duration & Price Preview */}
          <div className="bg-blue-50 p-4 rounded-xl flex justify-between items-center">
            <div>
              <label className="block text-xs font-semibold text-blue-800 uppercase tracking-wide mb-1">
                  {category === ServiceCategory.LAUNDRY ? 'Détail Calcul' : 
                   category === ServiceCategory.MARKET ? 'Articles' : 'Durée calculée'}
              </label>
              <div className="flex items-center space-x-2">
                <span className="font-bold text-lg text-blue-900">
                    {category === ServiceCategory.LAUNDRY 
                        ? `${clothesCount} vêtement${clothesCount > 1 ? 's' : ''}` 
                        : category === ServiceCategory.MARKET
                        ? `${marketItems.length} article(s)`
                        : `${duration > 0 ? duration.toFixed(2) : '--'} h`
                    }
                </span>
                {duration <= 0 && category !== ServiceCategory.MARKET && (
                   <div className="flex items-center text-red-500 text-xs ml-2">
                      <AlertCircle size={14} className="mr-1" />
                      <span>Horaires invalides</span>
                   </div>
                )}
              </div>
            </div>
            <div className="text-right">
              <div className="text-xs text-blue-600 font-medium mb-1">Prix Total Estimé</div>
              <div className="text-2xl font-bold text-blue-900">{price.toLocaleString()} FCFA</div>
            </div>
          </div>

          {/* Actions */}
          <div className="flex space-x-3 pt-2">
            <button
              type="button"
              onClick={() => setIsCreating(false)}
              className="flex-1 py-3 px-4 rounded-lg text-gray-600 font-medium hover:bg-gray-100 transition-colors"
            >
              Annuler
            </button>
            <button
              type="submit"
              disabled={(duration <= 0 && category !== ServiceCategory.MARKET) || (category === ServiceCategory.LAUNDRY && clothesCount < LAUNDRY_MIN_QTY)}
              className={`flex-1 py-3 px-4 rounded-lg text-white font-bold shadow-lg transition-colors flex justify-center items-center ${
                (duration > 0 || category === ServiceCategory.MARKET)
                ? 'bg-orange-500 hover:bg-orange-600 shadow-orange-200' 
                : 'bg-gray-400 cursor-not-allowed'
              }`}
            >
              {category === ServiceCategory.MARKET ? "Payer et Commander" : "Publier la demande"}
            </button>
          </div>
        </form>
      </div>
    );
  };

  const renderHome = () => (
      <div className="space-y-8 animate-fade-in">
        {/* Header Banner */}
        <div className="bg-gradient-to-r from-blue-600 to-blue-500 rounded-3xl p-8 text-white shadow-lg relative overflow-hidden">
            <div className="relative z-10">
            <h1 className="text-3xl font-bold mb-2">Bonjour, {currentUser.name} 👋</h1>
            <p className="text-blue-100 mb-6 max-w-lg">Trouvez la personne idéale pour votre ménage, cuisine ou petits travaux en quelques clics.</p>
            <button
                onClick={() => setIsCreating(true)}
                className="bg-orange-500 text-white px-6 py-3 rounded-full font-bold shadow-md hover:shadow-xl transform hover:-translate-y-0.5 transition-all flex items-center"
            >
                <Plus size={20} className="mr-2" />
                Nouvelle demande
            </button>
            </div>
            <div className="absolute right-0 bottom-0 opacity-10 transform translate-x-10 translate-y-10">
            <Calculator size={200} />
            </div>
        </div>

        {/* Active Missions List */}
        <div>
            <h2 className="text-xl font-bold text-gray-800 mb-4 flex items-center">
            <Clock size={20} className="mr-2 text-blue-500" />
            Vos missions récentes
            </h2>

            {myMissions.length === 0 ? (
            <div className="text-center py-12 bg-white rounded-2xl border border-dashed border-gray-300">
                <p className="text-gray-500">Aucune mission en cours.</p>
            </div>
            ) : (
            <div className="grid gap-4 md:grid-cols-2">
                {myMissions.map(mission => {
                const startDate = new Date(mission.date);
                const endTimeDisplay = mission.endTime 
                    ? new Date(mission.endTime).toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' })
                    : new Date(startDate.getTime() + mission.durationHours * 3600000).toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' });

                // Determine Market specific display logic
                const isMarket = mission.category === ServiceCategory.MARKET;
                const isMarketProcessed = isMarket && (mission.status === MissionStatus.IN_PROGRESS || mission.status === MissionStatus.COMPLETED);

                return (
                <div key={mission.id} className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100 hover:shadow-md transition-shadow">
                    <div className="flex justify-between items-start mb-3">
                    <span className={`px-3 py-1 rounded-full text-xs font-bold ${
                        mission.status === MissionStatus.COMPLETED ? 'bg-green-100 text-green-700' :
                        mission.status === MissionStatus.PENDING ? 'bg-yellow-100 text-yellow-700' :
                        mission.status === MissionStatus.DISPUTED ? 'bg-red-100 text-red-700' :
                        'bg-blue-100 text-blue-700'
                    }`}>
                        {isMarketProcessed ? "Commande Traitée" : mission.status}
                    </span>
                    <span className="font-bold text-gray-900">{mission.totalPrice.toLocaleString()} FCFA</span>
                    </div>
                    <h3 className="font-bold text-gray-800 mb-1">{mission.title}</h3>
                    <p className="text-sm text-gray-500 mb-4 line-clamp-2">{mission.description}</p>
                    {mission.category === ServiceCategory.LAUNDRY && mission.quantity && (
                        <p className="text-xs font-semibold text-blue-600 bg-blue-50 inline-block px-2 py-1 rounded mb-3">
                            <Shirt size={12} className="inline mr-1"/>
                            Quantité: {mission.quantity} vêtements
                        </p>
                    )}
                    {isMarket && !isMarketProcessed && (
                        <p className="text-xs font-semibold text-orange-600 bg-orange-50 inline-block px-2 py-1 rounded mb-3">
                            <ShoppingBasket size={12} className="inline mr-1"/>
                            {mission.deliveryWindow}
                        </p>
                    )}

                    {!isMarket && (
                    <div className="flex items-center text-sm text-gray-500 mb-2 bg-gray-50 p-2 rounded-lg">
                    <Calendar size={14} className="mr-2 text-blue-500" />
                    <span className="capitalize">
                        {startDate.toLocaleDateString('fr-FR', { weekday: 'short', day: 'numeric', month: 'short' })}
                    </span>
                    <span className="mx-2 text-gray-300">|</span>
                    <span className="font-medium text-gray-700">
                        {startDate.toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' })} - {endTimeDisplay}
                    </span>
                    </div>
                    )}

                    {/* ESTIMATED ARRIVAL BANNER */}
                    {mission.status === MissionStatus.ACCEPTED && mission.estimatedArrivalTime && (
                        <div className="bg-blue-600 text-white p-3 rounded-lg mb-3 animate-pulse flex items-center shadow-md">
                            <div className="mr-3 bg-white bg-opacity-20 p-2 rounded-full">
                                <Navigation size={20} className="text-white" />
                            </div>
                            <div>
                                <p className="font-bold text-sm">Le prestataire est en route !</p>
                                <p className="text-xs text-blue-100">
                                    Distance: {mission.estimatedDistance} km • Arrivée estimée : <span className="font-bold text-white">{new Date(mission.estimatedArrivalTime).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</span>
                                </p>
                            </div>
                        </div>
                    )}

                    {(mission.providerName || isMarket) && (
                    <div className="mt-4 pt-4 border-t">
                        <div className="flex items-center justify-between mb-3">
                            {mission.providerName && (
                            <div className="flex items-center">
                                <div className="w-8 h-8 bg-gray-200 rounded-full mr-3 flex items-center justify-center text-xs font-bold text-gray-600">
                                    {mission.providerName.charAt(0)}
                                </div>
                                <div>
                                    <p className="text-xs text-gray-500">Prestataire</p>
                                    <p className="text-sm font-medium">{mission.providerName}</p>
                                </div>
                            </div>
                            )}

                            {(mission.status === MissionStatus.IN_PROGRESS || mission.status === MissionStatus.ACCEPTED) && (
                            <div className="flex space-x-2">
                                <button
                                    onClick={() => openDispute(mission.id)} 
                                    className="p-2 text-red-500 hover:bg-red-50 rounded-full transition-colors" title="Signaler un problème"
                                >
                                    <AlertTriangle size={18} />
                                </button>
                            </div>
                            )}
                        </div>

                        <div className="space-y-2">
                            {mission.status === MissionStatus.IN_PROGRESS && !isMarket && (
                                <div className="bg-blue-50 p-3 rounded-lg border border-blue-100">
                                    <p className="text-xs text-blue-700 mb-2 flex items-center">
                                        <Clock size={12} className="mr-1" /> 
                                        Mission en cours - Paiement à la fin
                                    </p>
                                    <button 
                                        onClick={() => handleOpenPayment(mission)}
                                        className="w-full bg-green-600 text-white py-2 rounded-lg text-sm font-bold hover:bg-green-700 flex items-center justify-center shadow-lg shadow-green-200 animate-bounce-slow"
                                    >
                                        <Wallet size={16} className="mr-2" />
                                        Payer et Valider la fin
                                    </button>
                                </div>
                            )}

                            {(mission.status === MissionStatus.COMPLETED || (isMarket && mission.status === MissionStatus.IN_PROGRESS)) && !mission.clientRating && (
                                <button 
                                    onClick={() => openRating(mission.id)}
                                    className="w-full border border-yellow-400 text-yellow-600 py-2 rounded-lg text-sm font-bold hover:bg-yellow-50 flex items-center justify-center"
                                >
                                    <Star size={16} className="mr-2" />
                                    {isMarket ? "Noter la course" : "Noter la prestation"}
                                </button>
                            )}

                            {(mission.status === MissionStatus.COMPLETED || (isMarket && mission.status === MissionStatus.IN_PROGRESS)) && mission.clientRating && (
                                <div className="text-center text-sm text-yellow-600 font-medium flex justify-center items-center bg-yellow-50 p-2 rounded-lg">
                                    <Star size={14} fill="currentColor" className="mr-1" /> 
                                    Votre note: {mission.clientRating}/5
                                </div>
                            )}

                            {mission.status === MissionStatus.DISPUTED && (
                                <div className="bg-red-50 p-3 rounded-lg border border-red-100 text-sm text-red-700">
                                    <strong>Litige en cours :</strong><br/>
                                    "{mission.disputeReason}"
                                </div>
                            )}
                        </div>
                    </div>
                    )}
                </div>
                )})}
            </div>
            )}
        </div>
    </div>
  );

  const renderProfile = () => (
      <div className="bg-white rounded-2xl shadow-sm p-8 max-w-xl mx-auto animate-fade-in">
          <h2 className="text-2xl font-bold text-gray-800 mb-6 flex items-center">
              <UserIcon className="mr-2 text-blue-600" size={28} />
              Modifier mon profil
          </h2>

          <form onSubmit={handleProfileSubmit} className="space-y-6">
              {/* Avatar */}
              <div className="flex flex-col items-center mb-6">
                  <div className="w-24 h-24 rounded-full bg-gray-100 mb-3 overflow-hidden border-4 border-blue-50 relative group">
                      <img 
                        src={newAvatar || currentUser.avatarUrl} 
                        alt="Profil" 
                        className="w-full h-full object-cover"
                      />
                      <div className="absolute inset-0 bg-black bg-opacity-40 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity cursor-pointer">
                          <Camera className="text-white" size={24} />
                      </div>
                      <input 
                        type="file" 
                        accept="image/*"
                        onChange={handleFileChange}
                        className="absolute inset-0 opacity-0 cursor-pointer"
                      />
                  </div>
                  <span className="text-xs text-gray-500">Cliquez pour changer la photo</span>
              </div>

              <div className="space-y-4">
                  <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Nom Complet</label>
                      <div className="relative">
                          <UserIcon className="absolute left-3 top-3 text-gray-400" size={18} />
                          <input 
                            type="text" 
                            required
                            value={profileForm.name}
                            onChange={(e) => setProfileForm({...profileForm, name: e.target.value})}
                            className="w-full pl-10 p-2.5 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                          />
                      </div>
                  </div>

                  <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Numéro de téléphone</label>
                      <div className="relative">
                          <Phone className="absolute left-3 top-3 text-gray-400" size={18} />
                          <input 
                            type="tel" 
                            required
                            value={profileForm.phone}
                            onChange={(e) => setProfileForm({...profileForm, phone: e.target.value})}
                            className="w-full pl-10 p-2.5 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                          />
                      </div>
                  </div>

                  <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Ville</label>
                      <select
                          value={profileForm.city}
                          onChange={(e) => setProfileForm({...profileForm, city: e.target.value})}
                          className="w-full p-2.5 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                      >
                          {CITIES.map(c => <option key={c} value={c}>{c}</option>)}
                      </select>
                  </div>

                  <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Adresse (Quartier)</label>
                      <div className="relative">
                          <MapPin className="absolute left-3 top-3 text-gray-400" size={18} />
                          <input 
                            type="text" 
                            value={profileForm.address}
                            onChange={(e) => setProfileForm({...profileForm, address: e.target.value})}
                            className="w-full pl-10 p-2.5 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                          />
                      </div>
                  </div>
              </div>

              <button 
                  type="submit"
                  className="w-full bg-blue-600 text-white py-3 rounded-xl font-bold shadow-lg hover:bg-blue-700 transition-all flex items-center justify-center"
              >
                  <Save size={20} className="mr-2" />
                  Enregistrer les modifications
              </button>
          </form>
      </div>
  );

  if (isCreating) return (
      <>
        {renderCreateMission()}
        {renderPaymentModal()}
      </>
  );

  return (
    <div className="space-y-6">
        {renderModal()}
        {renderPaymentModal()}

        {/* Navigation Tabs */}
        <div className="flex justify-center bg-white p-1 rounded-xl shadow-sm max-w-xs mx-auto mb-8">
            <button 
                onClick={() => setActiveTab('HOME')}
                className={`flex-1 py-2 px-4 rounded-lg text-sm font-medium transition-colors ${activeTab === 'HOME' ? 'bg-blue-100 text-blue-700' : 'text-gray-500 hover:bg-gray-50'}`}
            >
                <Home size={16} className="inline mr-2 mb-0.5"/> Accueil
            </button>
            <button 
                onClick={() => setActiveTab('PROFILE')}
                className={`flex-1 py-2 px-4 rounded-lg text-sm font-medium transition-colors ${activeTab === 'PROFILE' ? 'bg-blue-100 text-blue-700' : 'text-gray-500 hover:bg-gray-50'}`}
            >
                <UserIcon size={16} className="inline mr-2 mb-0.5"/> Profil
            </button>
        </div>

        {activeTab === 'HOME' && renderHome()}
        {activeTab === 'PROFILE' && renderProfile()}
    </div>
  );
};

export default ClientDashboard;
]]></content>
